function footTaskFacet(task = {}) {
  const tags = new Set(task.tags || []);
  const lower = `${task.title || ""} ${task.text || ""}`.toLowerCase();
  if (tags.has("daily") || tags.has("discreet") || /alltag|zu hause|unter dem tisch|vorbeigehen|geheim/.test(lower)) return "daily";
  if (tags.has("hint") || /andeutung|nur ein wort|eine sekunde|beschreibt ein fussfoto/.test(lower)) return "hint";
  if (tags.has("dare") || /mutprobe|aussprechen|nicht anfassen/.test(lower)) return "dare";
  if (tags.has("evening-wish") || /abend|spaeter|erster griff|wunsch fuer heute/.test(lower)) return "evening";
  if (tags.has("story") || tags.has("fantasy") || /geschichte|dialog|echter moment|drei saetze/.test(lower)) return "story";
  if (tags.has("script") || /we2-regie|drei takte/.test(lower)) return "script";
  if (tags.has("foot-blowjob") || tags.has("blowjob")) return "blowjob";
  if (tags.has("photo") || tags.has("video") || tags.has("camera") || tags.has("media") || /foto|video|kamera|clip|link/.test(lower)) return "media";
  if (tags.has("care") || tags.has("washing") || tags.has("massage") || tags.has("pedicure") || /wasch|creme|oel|pflege|massier|naegel/.test(lower)) return "care";
  if (["kitchen", "shower", "bed", "sofa", "floor", "bathroom", "hotel", "mirror", "hallway", "wardrobe"].some((tag) => tags.has(tag)) || /kueche|dusche|bett|sofa|boden|bad|hotel|spiegel|flur/.test(lower)) return "place";
  if (tags.has("roleplay") || tags.has("service") || tags.has("dominance") || tags.has("control") || tags.has("worship") || /kniet|dient|befehl|regie|kontrolle|sklav/.test(lower)) return "dominance";
  if (tags.has("footjob") || tags.has("toejob") || tags.has("shoejob")) return "footjob";
  if (tags.has("position") || tags.has("sex")) return "position";
  if (tags.has("oral") || tags.has("toes") || tags.has("sole") || /leckt|lutscht|kuess/.test(lower)) return "oral";
  return "direct";
}

function footTitleKey(task = {}) {
  return String(task.title || task.id || "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ")
    .slice(0, 100);
}

function footApproachKey(task = {}) {
  const tags = new Set(task.tags || []);
  if (tags.has("foot-blowjob") || tags.has("blowjob")) return "blowjob-foot";
  if (tags.has("footjob") || tags.has("toejob") || tags.has("shoejob")) return "footjob";
  if (tags.has("photo") || tags.has("video") || tags.has("camera") || tags.has("media")) return "media";
  if (tags.has("feeding")) return "feeding";
  if (tags.has("nylons") || tags.has("shoes") || tags.has("boots") || tags.has("heels")) return "clothing";
  if (tags.has("care") || tags.has("washing") || tags.has("massage") || tags.has("pedicure")) return "care";
  if (tags.has("roleplay") || tags.has("service") || tags.has("dominance") || tags.has("control") || tags.has("worship")) return "power";
  if (tags.has("position") || tags.has("sex")) return "sex-position";
  if (tags.has("oral") || tags.has("toes") || tags.has("sole")) return "mouth";
  if (tags.has("message") || tags.has("talk") || tags.has("story") || tags.has("fantasy")) return "talk";
  return footTaskFacet(task);
}

function pickFootFacet() {
  const available = footFacetDefinitions.filter((facet) =>
    footFollowUps.some((task) => footTaskFacet(task) === facet.id)
  );
  if (!available.length) return "direct";
  const known = new Set(available.map((facet) => facet.id));
  const history = Array.isArray(state.footFacetHistory)
    ? state.footFacetHistory.filter((id) => known.has(id))
    : [];
  const recentLimit = Math.max(1, Math.min(available.length - 1, 4));
  const recent = new Set(history.slice(-recentLimit));
  const pool = available.filter((facet) => !recent.has(facet.id));
  const scoped = pool.length ? pool : available;
  const weighted = scoped.flatMap((facet) => Array.from({ length: Math.max(1, facet.weight) }, () => facet));
  const picked = weighted[Math.floor(Math.random() * weighted.length)] || scoped[0];
  state.footFacetHistory = [...history, picked.id].slice(-30);
  return picked.id;
}

