function footScriptTrackForContext(context) {
  const currentTrackId = currentTaskDraft?.footScriptTrack;
  if (currentTrackId) {
    const currentTrack = footScriptTracks.find((track) => track.id === currentTrackId);
    if (currentTrack) return currentTrack;
  }

  const contextTags = context.tags || new Set();
  const matches = footScriptTracks.filter((track) => {
    if (track.id === "foot-script-default") return false;
    if (track.block?.some((tag) => contextTags.has(tag))) return false;
    return track.match.some((tag) => contextTags.has(tag) || context.lower.includes(tag));
  });
  const remote = matches.find((track) => track.id === "foot-script-remote");
  if (remote) return remote;
  const location = matches.find((track) => [
    "foot-script-car",
    "foot-script-shower",
    "foot-script-kitchen",
    "foot-script-sofa-floor",
    "foot-script-nylon-shoes"
  ].includes(track.id));
  if (location) return location;
  return matches[0] || footScriptTracks.find((track) => track.id === "foot-script-default");
}

function cleanFootContinuationTitle(title = "") {
  const staleScriptTitle = new RegExp("^Dreh" + "buch\\s*(\\d+)?\\s*:\\s*", "i");
  return String(title)
    .replace(staleScriptTitle, (match, number) => number ? `Schritt ${number}: ` : "")
    .trim();
}

function buildScriptedFootContinuation() {
  const context = footContinuationContext();
  const track = footScriptTrackForContext(context);
  const steps = track?.steps || [];
  if (!steps.length) return null;
  const allUsedSteps = Array.isArray(currentTaskDraft?.footScriptSteps) ? currentTaskDraft.footScriptSteps : [];
  const usedSteps = allUsedSteps.filter((step) => step.track === track.id);
  if (usedSteps.length >= steps.length) {
    return {
      id: `${track.id}-end-${usedSteps.length + 1}`,
      title: `Schritt ${usedSteps.length + 1}: Kante halten`,
      text: "Kein neuer Sprung. Wiederholt das staerkste Fußdetail aus dem letzten Schritt und beendet die Szene danach klar.",
      tags: ["foot-more", "control", "feet", track.id],
      scriptTrack: track.id,
      scriptStep: usedSteps.length + 1,
      scriptDone: true
    };
  }
  const stepIndex = Math.min(usedSteps.length, steps.length - 1);
  const base = steps[stepIndex];
  return {
    id: `${track.id}-${stepIndex + 1}`,
    title: cleanFootContinuationTitle(base.title),
    text: base.text,
    tags: [...(base.tags || []), track.id],
    scriptTrack: track.id,
    scriptStep: stepIndex + 1,
    scriptDone: stepIndex >= steps.length - 1
  };
}

