function mediaPromptAllowedForActivePlayer(prompt = "") {
  const actorIndex = activePlayContext().actorIndex;
  const text = String(prompt).toLowerCase();
  if (actorIndex === 0) {
    if (text.startsWith("jenny-auftrag:") || text.startsWith("jenny-solo:")) return false;
    return !/nylon|strumpf/.test(text);
  }
  if (actorIndex === 1 && (text.startsWith("christian-auftrag:") || text.startsWith("christian-solo:"))) return false;
  return true;
}

function mediaPromptPoolForActivePlayer(options = {}) {
  const { strict = false } = options;
  const actorIndex = activePlayContext().actorIndex;
  const playerPrompts = (mediaPromptsByPlayer[actorIndex] || []).filter(mediaPromptAllowedForActivePlayer);
  const sharedPrompts = mediaPrompts.filter(mediaPromptAllowedForActivePlayer);
  if (strict && playerPrompts.length) return playerPrompts;
  const pool = [...playerPrompts, ...sharedPrompts];
  return pool.length ? pool : playerPrompts.length ? playerPrompts : sharedPrompts;
}

