function positionHasText(position, pattern) {
  return pattern.test(`${position.title || ""} ${position.setup || ""} ${position.focus || ""}`.toLowerCase());
}

function derivePositionDifficulty(position) {
  if (position.difficulty) return position.difficulty;
  if (positionHasText(position, /stehend|wand|arbeitsplatte|kuechenkante|supported|rising|bamboo|reverse/)) return "Fortgeschritten";
  if (positionHasText(position, /seitlich|loefel|sofa|stuhl|bettkante|lotus|oral|69/)) return "Mittel";
  return "Leicht";
}

function cleanPositionImageUrl(position) {
  const url = position.imageUrl || "";
  if (/commons\.wikimedia\.org\/wiki\/File:/i.test(url)) return url;
  if (/File:10_Vaginal_Sex_Positions\.png/i.test(url)) return url;
  return "";
}

function positionSourceUrl(position, cleanImageUrl) {
  if (cleanImageUrl) return cleanImageUrl;
  if (/wikisource\.org/i.test(position.imageUrl || "")) return position.imageUrl;
  if (/Kama:/i.test(position.title || "")) return positionCuratedLinks.kamaOverview;
  return positionCommonsCategory;
}

function positionImageSearchTerm(position) {
  if (position.searchTerm) return position.searchTerm;
  if (positionImageSearchTerms[position.title]) return positionImageSearchTerms[position.title];
  const name = (position.name || position.title || "sex position")
    .replace(/^Kama:\s*/i, "")
    .replace(/^Modern:\s*/i, "");
  return `${name} sex position illustration`;
}

function positionImageSearchUrl(position) {
  return `${positionImageSearchBase}${encodeURIComponent(positionImageSearchTerm(position))}`;
}

function isBlockedPositionSource(url = "") {
  return /commons\.wikimedia\.org|womenshealthmag\.com|cosmopolitan\.com/i.test(String(url || ""));
}

function isDirectPositionUrl(url = "") {
  return /sexpositions\.club\/positions\/\d+\.html/i.test(String(url || ""));
}

function positionVisualKey(position = {}) {
  const directUrl = isDirectPositionUrl(position.curatedUrl)
    ? position.curatedUrl
    : isDirectPositionUrl(position.sourceUrl)
      ? position.sourceUrl
      : "";
  return (directUrl || position.curatedUrl || position.title || "").toLowerCase();
}

function uniquePositionsByVisualKey(items = []) {
  const seen = new Set();
  return items.filter((item) => {
    const key = positionVisualKey(item);
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

