    fantasie: ["fantasie", "fantasy", "imagination", "dream", "scene"],
    beziehung: ["beziehung", "relationship", "pair", "couple", "bond"],
    kommunikation: ["kommunikation", "communication", "talk", "message", "question"],
    mut: ["mut", "courage", "brave", "overcome", "confidence"],
    vertrauen: ["vertrauen", "trust", "consent", "boundary", "care"],
    spielerisch: ["spielerisch", "playful", "play", "tease", "fun"],
    foot_focus: ["feet", "foot", "fuss", "fuesse", "footjob", "toes", "toe", "nylons", "shoe", "massage"],
    feet: ["feet", "foot", "fuss", "fuesse", "footjob", "toes", "toe", "nylons", "shoe", "massage"],
