truthOrDareCards.push(...buildCoverageTestCards());

function getShortGameSelectionCards(selection = {}, context = truthDareActorContext()) {
  const selectionChoice = String(selection.choice || "").trim();
  const modeId = normalizeTruthGameMode(selection.modeId || context.modeId || "");
  const topic = normalizeCardTopic(selection.topic || context.topic || "");
  const safeContext = {
    ...context,
    ...buildCardDrawContext({ modeId, topic, drawerIndex: Number.isInteger(selection.drawerIndex) ? selection.drawerIndex : context.actorIndex }),
    choice: selectionChoice || "surprise",
    modeId,
    topic
  };
  const settings = state.gameSettings || defaultGameSettings;
  return truthOrDareCards
    .map((card) => normalizeShortGameCard(card))
    .filter((card) => {
      if (!settings.anal && (card.tags || []).includes("anal")) return false;
      if (!truthDareCardAllowedForActivePlayer(card)) return false;
      const rawText = resolveTruthDareValue(card.text, context) || "";
      if (!taskContextAllowed(card.tags || [], `${card.title || ""} ${rawText}`)) return false;
      if (safeContext.modeId && !truthCardMatchesMode(card, safeContext.modeId)) return false;
      if (safeContext.topic) {
        const cardTopic = inferCardTopic(card);
        if (cardTopic && cardTopic !== safeContext.topic && !(card.tags || []).includes(safeContext.topic)) return false;
      }
      if (selectionChoice && selectionChoice !== "surprise" && card.type !== selectionChoice) return false;
      if (safeContext.modeId === "intense" && !safeContext.allowedModes?.intense) return false;
      return true;
    })
    .filter((card) => isCardPlayable(card, { ...safeContext, maxAllowedIntensity: safeContext.maxAllowedIntensity || 5 }));
}

function getAvailableGameOptions(context = truthDareActorContext()) {
  const safeContext = context && typeof context === "object" ? context : truthDareActorContext();
  const modes = truthGameModes.map((mode) => {
    const choiceCounts = {
      truth: getShortGameSelectionCards({ choice: "truth", modeId: mode.id, topic: safeContext.topic }, safeContext).length,
      dare: getShortGameSelectionCards({ choice: "dare", modeId: mode.id, topic: safeContext.topic }, safeContext).length,
      surprise: getShortGameSelectionCards({ choice: "surprise", modeId: mode.id, topic: safeContext.topic }, safeContext).length
    };
    const availableCount = Math.max(choiceCounts.truth, choiceCounts.dare, choiceCounts.surprise);
    return {
      ...mode,
      available: availableCount > 0,
      availableCount,
      choiceCounts
    };
  });
  const choiceCounts = {
    truth: getShortGameSelectionCards({ choice: "truth", modeId: safeContext.modeId, topic: safeContext.topic }, safeContext).length,
    dare: getShortGameSelectionCards({ choice: "dare", modeId: safeContext.modeId, topic: safeContext.topic }, safeContext).length,
    surprise: getShortGameSelectionCards({ choice: "surprise", modeId: safeContext.modeId, topic: safeContext.topic }, safeContext).length
  };
  return {
    modes,
    choices: [
      { id: "truth", label: "Wahrheit", available: choiceCounts.truth > 0, count: choiceCounts.truth },
      { id: "dare", label: "Pflicht", available: choiceCounts.dare > 0, count: choiceCounts.dare },
      { id: "surprise", label: "Ãœberraschung", available: choiceCounts.surprise > 0, count: choiceCounts.surprise }
    ]
  };
}

function getContentCoverageMatrix(context = truthDareActorContext()) {
  const safeContext = context && typeof context === "object" ? context : truthDareActorContext();
  const matrix = SHORT_GAME_COVERAGE_TOPICS.map((topic) => {
    const row = { topicId: topic, topicLabel: topic, modes: {}, total: 0 };
    SHORT_GAME_COVERAGE_MODE_SPECS.forEach(({ mode }) => {
      const counts = {
        truth: getShortGameSelectionCards({ choice: "truth", modeId: mode, topic }, safeContext).length,
        dare: getShortGameSelectionCards({ choice: "dare", modeId: mode, topic }, safeContext).length,
        surprise: getShortGameSelectionCards({ choice: "surprise", modeId: mode, topic }, safeContext).length
      };
      row.modes[mode] = {
        truth: counts.truth,
        dare: counts.dare,
        surprise: counts.surprise,
        playable: Math.max(counts.truth, counts.dare, counts.surprise) > 0
      };
      row.total += counts.truth + counts.dare + counts.surprise;
    });
    return row;
  });
  const disabledCombos = [];
  matrix.forEach((row) => {
    Object.entries(row.modes).forEach(([mode, entry]) => {
      if (!entry.playable) disabledCombos.push({ topicId: row.topicId, modeId: mode });
    });
  });
  return {
    matrix,
    disabledCombos,
    summary: {
      totalPlayable: matrix.reduce((sum, row) => sum + row.total, 0),
      disabledCount: disabledCombos.length
    }
  };
}

function pickCardForSelection(selection = {}, context = truthDareActorContext()) {
  const safeSelection = typeof selection === "string" ? { choice: selection } : (selection && typeof selection === "object" ? selection : {});
  const selectionChoice = String(safeSelection.choice || "").trim() || "surprise";
  const cards = getShortGameSelectionCards(safeSelection, context);
  if (!cards.length) return null;
  const modeId = normalizeTruthGameMode(safeSelection.modeId || context.modeId || "");
  const drawerIndex = Number.isInteger(safeSelection.drawerIndex) ? safeSelection.drawerIndex : context.actorIndex;
  return pickWithoutQuickRepeat(
    cards,
    shortGameSelectionKey({ ...safeSelection, choice: selectionChoice, modeId, drawerIndex }),
    (item) => item.id,
    (item) => scoreShortGameCard(item, { choice: selectionChoice, modeId, ...context, drawerIndex }),
    antiRepeatLimit(cards.length, 0.94)
  );
}

function profileTextForIndex(profileIndex = 0, currentState = state) {
  const profile = normalizeProfile(currentState.profiles?.[profileIndex] || {});
  const questionText = activeProfileQuestions(profileIndex)
    .map((question) => String(profile.answers?.[question.id] || "").trim())
    .filter(Boolean)
    .join(" ");
  const hiddenText = Object.values(profile.hiddenAnswers || {}).join(" ");
  const rankingText = normalizeTryRanking(profile.tryRanking || [])
    .map((item) => `${item.label} ${(item.tags || []).join(" ")}`.repeat(Math.max(1, Number(item.rating) || 0)))
    .join(" ");
  return [
    currentState.likesOne,
    currentState.likesTwo,
    profile.about,
    profile.questions,
    questionText,
    hiddenText,
    rankingText
  ].join(" ").toLowerCase();
}

function profileTopicScore(profileIndex = 0, topicId = "", currentState = state) {
  const text = profileTextForIndex(profileIndex, currentState);
  const aliases = topicAliases(topicId);
  const perspective = normalizeProfile(currentState.profiles?.[profileIndex] || {}).interestPerspective?.[normalizeCardTopic(topicId)] || {};
  const tagHits = aliases.reduce((sum, alias) => sum + (text.includes(alias) ? 2 : 0), 0);
  const explicit = Math.max(0, Number(perspective.selfInterest) || 0) * 2;
  const comfort = Math.max(0, Number(perspective.comfortBeingFocus) || 0) + Math.max(0, Number(perspective.comfortGivingFocus) || 0);
  const curiosity = perspective.status === "curious" ? 1 : 0;
  const blocked = perspective.status === "taboo" || perspective.status === "not_for_me" ? -8 : 0;
  return tagHits + explicit + comfort + curiosity + blocked;
}

function profileIntensityCeiling(profileIndex = 0, currentState = state) {
  const profile = normalizeProfile(currentState.profiles?.[profileIndex] || {});
  const text = profileTextForIndex(profileIndex, currentState);
  const learned = normalizeTryRanking(profile.tryRanking || []).reduce((sum, item) => sum + Math.max(0, Number(item.rating) || 0), 0);
  const directSignals = /direkt|hart|intensiv|mehr|haerter|explizit|mutig/.test(text) ? 1 : 0;
  const softSignals = /sanft|ruhig|langsam|vorsichtig|liebevoll|zart/.test(text) ? 1 : 0;
  let ceiling = 3 + directSignals + Math.floor(learned / 8) - softSignals;
  if (/tabu|nicht|kein|nie/.test(text) && !/vielleicht|curious|neugierig/.test(text)) ceiling -= 1;
  return Math.max(1, Math.min(5, ceiling));
}

function buildCouplePreferenceModel(currentState = state) {
  const drawerTexts = [profileTextForIndex(0, currentState), profileTextForIndex(1, currentState)];
  const drawerTags = drawerTexts.map((text) => new Set(inferTaskTags(text, text, [])));
  const sharedLikes = [...drawerTags[0]].filter((tag) => drawerTags[1].has(tag));
  const blockedTags = new Set();
  const softInterests = new Set();

  const blockedWords = [String(currentState.boundaries || ""), String(currentState.likesOne || ""), String(currentState.likesTwo || "")]
    .join(" ").toLowerCase();
  ["tabu", "stop", "nicht", "kein", "nie"].forEach((word) => {
    if (blockedWords.includes(word)) blockedTags.add(word);
  });
  inferTaskTags(blockedWords, blockedWords, []).forEach((tag) => blockedTags.add(tag));
  [0, 1].forEach((profileIndex) => {
    const perspective = normalizeProfile(currentState.profiles?.[profileIndex] || {}).interestPerspective || {};
    Object.entries(perspective).forEach(([topicId, item]) => {
      if (!item || (item.status !== "taboo" && item.status !== "not_for_me")) return;
      topicAliases(topicId).forEach((tag) => blockedTags.add(tag));
    });
  });

  const allTags = new Set([...drawerTags[0], ...drawerTags[1]]);
  allTags.forEach((tag) => {
    if (sharedLikes.includes(tag)) return;
    if (drawerTags[0].has(tag) || drawerTags[1].has(tag)) softInterests.add(tag);
  });

  const preferredTone = sharedLikes.some((tag) => ["care", "soft", "massage"].includes(tag))
    ? "sanft"
    : sharedLikes.some((tag) => ["play", "tease", "choice"].includes(tag))
      ? "verspielt"
      : sharedLikes.some((tag) => ["direct", "dirty", "command"].includes(tag))
        ? "direkt"
        : sharedLikes.some((tag) => ["dominance", "control"].includes(tag))
          ? "dominant"
          : "romantisch";

  const preferredFormats = [...new Set([
    sharedLikes.some((tag) => ["talk", "question", "message"].includes(tag)) ? "talk" : null,
    sharedLikes.some((tag) => ["message", "photo", "video", "audio"].includes(tag)) ? "message" : null,
    sharedLikes.some((tag) => ["touch", "massage", "feet", "body"].includes(tag)) ? "touch" : null,
    sharedLikes.some((tag) => ["position", "scene"].includes(tag)) ? "game" : null,
    sharedLikes.some((tag) => ["photo", "video"].includes(tag)) ? "photo" : null,
    sharedLikes.some((tag) => ["date", "evening", "dayplay"].includes(tag)) ? "date" : null,
    sharedLikes.some((tag) => ["challenge", "experiment", "novelty"].includes(tag)) ? "challenge" : null
  ].filter(Boolean))];

  const intensityCeiling = Math.min(profileIntensityCeiling(0, currentState), profileIntensityCeiling(1, currentState), Number(currentState.gameSettings?.directness) || 5);
  const noveltyLevel = sharedLikes.some((tag) => ["experiment", "novelty", "new"].includes(tag))
    ? "hoch"
    : softInterests.size > 8
      ? "mittel"
      : "niedrig";

  const dailyMoodHints = [
    sharedLikes.includes("dayplay") ? "Alltag" : "",
    sharedLikes.includes("evening") ? "Abend" : "",
    sharedLikes.includes("weekend") ? "Wochenende" : "",
    sharedLikes.includes("private") ? "privat" : ""
  ].filter(Boolean);

  const explanation = sharedLikes.length
    ? `Gemeinsam stark: ${sharedLikes.slice(0, 4).join(", ")}.`
    : "Die App bleibt vorsichtig und orientiert sich an den sichtbaren Profil-Signalen.";

  return {
    sharedLikes,
    softInterests: [...softInterests],
    blockedTags: [...blockedTags],
    intensityCeiling,
    preferredTone,
    preferredFormats,
    noveltyLevel,
    dailyMoodHints,
    explanation
  };
}

function getTopicDynamicForDrawer(topicId, drawerId, currentState = state) {
  const safeDrawerIndex = Number(drawerId) === 1 ? 1 : 0;
  const partnerIndex = safeDrawerIndex === 0 ? 1 : 0;
  const topic = normalizeCardTopic(topicId);
  const model = buildCouplePreferenceModel(currentState);
  const drawerPerspective = normalizeProfile(currentState.profiles?.[safeDrawerIndex] || {}).interestPerspective?.[topic] || {};
  const partnerPerspective = normalizeProfile(currentState.profiles?.[partnerIndex] || {}).interestPerspective?.[topic] || {};
  const drawerScore = profileTopicScore(safeDrawerIndex, topic, currentState);
  const partnerScore = profileTopicScore(partnerIndex, topic, currentState);
  const drawerBlocked = drawerPerspective.status === "taboo" || drawerPerspective.status === "not_for_me";
  const partnerBlocked = partnerPerspective.status === "taboo" || partnerPerspective.status === "not_for_me";
  const maxAllowedIntensity = Math.min(model.intensityCeiling, profileIntensityCeiling(safeDrawerIndex, currentState), profileIntensityCeiling(partnerIndex, currentState));

  let drawerRole = "neutral";
  let partnerRole = "neutral";
  let matchType = "unknown";

  if (drawerBlocked || partnerBlocked) {
    drawerRole = drawerBlocked ? "blocked" : drawerRole;
    partnerRole = partnerBlocked ? "blocked" : partnerRole;
    matchType = "blocked";
  } else if (drawerScore >= 7 && partnerScore >= 7) {
    drawerRole = "active_interest";
    partnerRole = "active_interest";
    matchType = "shared_interest";
  } else if (drawerScore >= 7 && (partnerPerspective.comfortBeingFocus >= 3 || partnerScore >= 4)) {
    drawerRole = "active_interest";
    partnerRole = "enjoys_being_desired";
    matchType = "asymmetric_match";
  } else if (partnerScore >= 7 && (drawerPerspective.comfortBeingFocus >= 3 || drawerScore >= 4)) {
    drawerRole = "enjoys_being_desired";
    partnerRole = "active_interest";
    matchType = "asymmetric_match";
  } else if (drawerScore >= 7 || partnerScore >= 7) {
    drawerRole = drawerScore >= 7 ? "active_interest" : (drawerPerspective.status === "curious" ? "curious" : "neutral");
    partnerRole = partnerScore >= 7 ? "active_interest" : (partnerPerspective.status === "curious" ? "curious" : "neutral");
    matchType = "one_sided_only";
  } else if (drawerPerspective.status === "curious" || partnerPerspective.status === "curious") {
    drawerRole = drawerPerspective.status === "curious" ? "curious" : drawerRole;
    partnerRole = partnerPerspective.status === "curious" ? "curious" : partnerRole;
    matchType = "one_sided_only";
  }

  const allowedModes = {
    intro: !drawerBlocked && !partnerBlocked && maxAllowedIntensity >= 1,
    playful: !drawerBlocked && !partnerBlocked && maxAllowedIntensity >= 2,
    direct: !drawerBlocked && !partnerBlocked && maxAllowedIntensity >= 3,
    intense: !drawerBlocked && !partnerBlocked && maxAllowedIntensity >= 4 && drawerPerspective.comfortGivingFocus >= 2 && partnerPerspective.comfortBeingFocus >= 2
  };

  const explanation = drawerBlocked || partnerBlocked
    ? "Dieses Thema ist fuer eine Seite blockiert und wird nicht als Karte angeboten."
    : matchType === "shared_interest"
      ? "Beide zeigen klar Interesse, deshalb darf die App das Thema spielerisch vertiefen."
      : matchType === "asymmetric_match"
        ? "Eine Person zieht aktiv, die andere kann sich darauf einlassen, ohne das Thema selbst zu besitzen."
        : matchType === "one_sided_only"
          ? "Das Thema bleibt vorsichtig und startet nur in einer leichten, pruefenden Form."
          : model.explanation;

  return {
    topicId: topic,
    drawerRole,
    partnerRole,
    matchType,
    allowedModes,
    maxAllowedIntensity,
    explanation
  };
}

function buildCardDrawContext({ modeId = "", topic = "", drawerIndex = Number(state.activeIndex) === 1 ? 1 : 0 } = {}) {
  const safeDrawerIndex = Number.isInteger(drawerIndex) && drawerIndex === 1 ? 1 : 0;
  const partnerIndex = safeDrawerIndex === 0 ? 1 : 0;
  const safeMode = normalizeCardModeId(modeId || getSelectedCardMode());
  const topicDynamic = getTopicDynamicForDrawer(topic || getSelectedCardTopic(), safeDrawerIndex, state);
  const preferenceModel = buildCouplePreferenceModel(state);
  return {
    drawerIndex: safeDrawerIndex,
    partnerIndex,
    topic: normalizeCardTopic(topic || getSelectedCardTopic()),
    modeId: safeMode,
    drawerRole: topicDynamic.drawerRole || "either",
    partnerRole: topicDynamic.partnerRole || "either",
    matchType: topicDynamic.matchType || "unknown",
    allowedModes: topicDynamic.allowedModes || {},
    maxAllowedIntensity: safeMode ? Math.min(topicDynamic.maxAllowedIntensity || 5, Number(elements.intensityRange?.value) || Number(state.gameSettings?.directness) || 5) : 5,
    topicIntensityCeiling: topicDynamic.maxAllowedIntensity || 5,
    blockedTags: Array.isArray(preferenceModel.blockedTags) ? preferenceModel.blockedTags : [],
    preferredTags: Array.isArray(preferenceModel.sharedLikes) ? preferenceModel.sharedLikes : [],
    preferenceModel,
    drawerName: state.players[safeDrawerIndex] || (safeDrawerIndex === 0 ? "Christian" : "Jenny"),
    partnerName: state.players[partnerIndex] || (partnerIndex === 0 ? "Christian" : "Jenny"),
    drawerProfile: state.profiles[safeDrawerIndex] || {},
    partnerProfile: state.profiles[partnerIndex] || {}
  };
}

function cardMatchesMode(card, modeId = "", context = buildCardDrawContext()) {
  const safeMode = normalizeCardModeId(modeId);
  if (!safeMode) return true;
  const config = CARD_MODE_CONFIG[safeMode];
  if (!config) return true;
  const normalized = normalizeCardCompletion(card);
  const tags = new Set(normalized.tags || []);
  const contextBlockedTags = new Set(Array.isArray(context.blockedTags) ? context.blockedTags : []);
  if (Number(normalized.intensity) < config.minIntensity || Number(normalized.intensity) > config.maxIntensity) return false;
  if (safeMode && context.allowedModes && context.allowedModes[safeMode] === false) return false;
  if (config.blockedTags.some((tag) => tags.has(tag))) return false;
  if ([...contextBlockedTags].some((tag) => tags.has(tag))) return false;
  if (Array.isArray(card.modes) && card.modes.length && !card.modes.includes(safeMode)) return false;
  if (normalized.mode && normalized.mode !== safeMode && !config.preferredTags.some((tag) => tags.has(tag))) return false;
  if (context.topic) {
    const topic = inferCardTopic(normalized);
    if (topic && topic !== context.topic && !(normalized.tags || []).includes(context.topic)) return false;
  }
  if (Array.isArray(normalized.matchTypes) && normalized.matchTypes.length && context.matchType && !normalized.matchTypes.includes(context.matchType)) return false;
  if (normalized.drawerRole && normalized.drawerRole !== "either" && context.drawerRole && normalized.drawerRole !== context.drawerRole) return false;
  if (normalized.targetRole && normalized.targetRole !== "either" && context.partnerRole && normalized.targetRole !== context.partnerRole) return false;
  if (normalized.focusPerson === "drawer" && context.drawerRole === "blocked") return false;
  if (normalized.focusPerson === "partner" && context.partnerRole === "blocked") return false;
  if (normalized.focusPerson === "both" && (context.drawerRole === "blocked" || context.partnerRole === "blocked")) return false;
  if (normalized.requiresBothConsent && safeMode === "intense" && context.maxAllowedIntensity < 4) return false;
  return true;
}

function scoreCardForMode(card, modeId = "", context = buildCardDrawContext()) {
  const safeMode = normalizeCardModeId(modeId);
  const config = safeMode ? CARD_MODE_CONFIG[safeMode] : null;
  const normalized = normalizeCardCompletion(card);
  const tags = new Set(normalized.tags || []);
  let score = cardWeight(normalized);
  if (config) {
    config.preferredTags.forEach((tag) => {
      if (tags.has(tag)) score += 3;
    });
    config.blockedTags.forEach((tag) => {
      if (tags.has(tag)) score -= 4;
    });
    if (normalized.mode === safeMode) score += 4;
    if (Array.isArray(normalized.modes) && normalized.modes.includes(safeMode)) score += 5;
    const intensity = Number(normalized.intensity) || 1;
    const distance = Math.abs(Math.min(config.maxIntensity, Math.max(config.minIntensity, intensity)) - intensity);
    score += Math.max(0, 5 - distance);
  }
  if (context.topic && inferCardTopic(normalized) === context.topic) score += 4;
  if (Array.isArray(normalized.matchTypes) && normalized.matchTypes.length && context.matchType && normalized.matchTypes.includes(context.matchType)) score += 4;
  if (normalized.drawerRole && normalized.drawerRole !== "either") score += 1;
  if (normalized.targetRole && normalized.targetRole !== "either") score += 1;
  if (normalized.focusPerson === "drawer" && context.drawerIndex === Number(state.activeIndex)) score += 1;
  if (normalized.focusPerson === "partner" && context.partnerIndex === Number(state.activeIndex)) score += 1;
  if (Array.isArray(context.preferredTags) && context.preferredTags.some((tag) => tags.has(tag))) score += 2;
  return score;
}

function getCardsForMode(cards = [], modeId = "", context = buildCardDrawContext()) {
  const safeMode = normalizeCardModeId(modeId);
  const filtered = cards.filter((card) => cardMatchesMode(card, safeMode, context));
  if (!safeMode) return filtered;
  return filtered.sort((a, b) => scoreCardForMode(b, safeMode, context) - scoreCardForMode(a, safeMode, context));
}

function isCardPlayable(card, context = buildCardDrawContext()) {
  if (!card || typeof card !== "object") return false;
  const normalized = normalizeCardCompletion(card);
  if (!String(normalized.id || card.id || "").trim()) return false;
  if (!String(normalized.title || "").trim()) return false;
  if (!String(typeof normalized.text === "function" ? "" : normalized.text || "").trim()) return false;
  if (!String(normalized.type || "").trim()) return false;
  if (!normalized.mode) return false;
  if (!Number.isFinite(Number(normalized.intensity))) return false;
  if (!CARD_COMPLETION_TYPES.has(normalized.completionType)) return false;
  if (normalized.completionType === "choice" && !normalized.choices.length) return false;
  if (normalized.completionType === "timer" && !Number(card.duration || normalized.duration || 0)) return false;
  if (["photo", "video", "audio"].includes(normalized.completionType) && !normalized.saveToLibrary) return false;
  if (["photo", "video", "audio"].includes(normalized.completionType) && !normalized.libraryCategory) return false;
  if (normalized.intensity > Number(context.maxAllowedIntensity || 5)) return false;
  if (!cardMatchesMode(normalized, context.modeId, context)) return false;
  if (Array.isArray(normalized.matchTypes) && normalized.matchTypes.length && context.matchType && !normalized.matchTypes.includes(context.matchType)) return false;
  if (normalized.drawerRole && normalized.drawerRole !== "either" && context.drawerRole && normalized.drawerRole !== context.drawerRole) return false;
  if (normalized.targetRole && normalized.targetRole !== "either" && context.partnerRole && normalized.targetRole !== context.partnerRole) return false;
  if (normalized.focusPerson === "drawer" && context.drawerRole === "blocked") return false;
  if (normalized.focusPerson === "partner" && context.partnerRole === "blocked") return false;
  if (normalized.focusPerson === "both" && (context.drawerRole === "blocked" || context.partnerRole === "blocked")) return false;
  if (Array.isArray(normalized.modes) && normalized.modes.length && context.modeId && !normalized.modes.includes(context.modeId)) return false;
  if (normalized.requiresBothConsent && context.modeId === "intense" && context.maxAllowedIntensity < 4) return false;
  return true;
}

function buildCardSession(card, context = buildCardDrawContext()) {
  const normalized = normalizeCardCompletion(card);
  const now = new Date().toISOString();
  return {
    sessionId: `${Date.now()}-${Math.random().toString(36).slice(2)}`,
    cardId: normalized.id,
    cardTitle: normalized.title,
    cardType: normalized.type,
    topic: normalized.topic,
    mode: normalized.mode,
    intensity: normalized.intensity,
    drawerRole: context.drawerRole || "either",
    partnerRole: context.partnerRole || "either",
    matchType: context.matchType || "unknown",
    openedBy: context.drawerIndex,
    openedAt: now,
    acceptedAt: "",
    completedAt: "",
    abortedAt: "",
    status: "preview",
    completionType: normalized.completionType,
    completionDataIds: [],
    feedback: null,
    card: normalized
  };
}

function allCardSources() {
  return [...cards, ...state.customCards].map((card) => normalizeCardCompletion(card));
}

function allRawCardSources() {
  return [...cards, ...state.customCards];
}

function validateAllCards() {
  const rows = allRawCardSources().map((rawCard) => {
    const card = normalizeCardCompletion(rawCard);
    const context = buildCardDrawContext({ modeId: card.mode, topic: card.topic });
    context.maxAllowedIntensity = 5;
    const issues = [];
    if (!String(card.id || "").trim()) issues.push("missing-id");
    if (!String(rawCard.title || "").trim()) issues.push("missing-title");
    if (!String(typeof rawCard.text === "function" ? "" : rawCard.text || "").trim()) issues.push("missing-text");
    if (!String(card.type || "").trim()) issues.push("missing-type");
    if (!String(card.mode || "").trim()) issues.push("missing-mode");
    if (!Number.isFinite(Number(card.intensity))) issues.push("missing-intensity");
    if (!Object.prototype.hasOwnProperty.call(shortGameTypes, card.gameType)) issues.push("unsupported-gameType");
    if (!CARD_COMPLETION_TYPES.has(card.completionType)) issues.push("invalid-completionType");
    if (card.completionType === "choice" && !(card.choices || []).length) issues.push("choice-without-choices");
    if (card.completionType === "timer" && !Number(card.duration || 0)) issues.push("timer-without-duration");
    if (["photo", "video", "audio"].includes(card.completionType) && (!card.saveToLibrary || !card.libraryCategory)) issues.push("media-without-library-target");
    if (!isCardPlayable(card, context)) issues.push("unplayable");
    return {
      id: card.id || "",
      title: card.title || "",
      type: card.type || card.category || "",
      completionType: card.completionType || "",
      status: issues.length ? "needs-review" : "ok",
      issues: issues.join(", ")
    };
  });
  console.table(rows);
  return rows;
}

function simulateAcceptTask(cardId = "") {
  const card = allRawCardSources().find((item) => normalizeCardCompletion(item).id === cardId) || allRawCardSources()[0];
  if (!card) return null;
  const beforePoints = getTotalPoints();
  const session = buildCardSession(card, buildCardDrawContext({ modeId: normalizeCardCompletion(card).mode, topic: normalizeCardCompletion(card).topic }));
  state.currentCardSession = session;
  acceptTask(card, buildCardDrawContext({ modeId: session.mode, topic: session.topic, drawerIndex: session.openedBy }));
  return {
    cardId: normalizeCardCompletion(card).id,
    accepted: Boolean(state.activeTasks?.some((task) => task.cardId === normalizeCardCompletion(card).id)),
    status: state.activeTask?.status || "",
    visible: Boolean(state.activeTask?.visible),
    pointsChanged: getTotalPoints() - beforePoints
  };
}

function simulateZapTask(cardId = "") {
  const card = allRawCardSources().find((item) => normalizeCardCompletion(item).id === cardId) || allRawCardSources()[0];
  if (!card) return null;
  const beforePoints = getTotalPoints();
  state.currentCardSession = buildCardSession(card, buildCardDrawContext({ modeId: normalizeCardCompletion(card).mode, topic: normalizeCardCompletion(card).topic }));
  zapSuggestedTask(normalizeCardCompletion(card).id, "simulation");
  return {
    cardId: normalizeCardCompletion(card).id,
    activeTaskCreated: Boolean(state.activeTasks?.some((task) => task.cardId === normalizeCardCompletion(card).id)),
    pointsChanged: getTotalPoints() - beforePoints,
    currentCardId: state.currentCardSession?.cardId || ""
  };
}

function simulateCloseTaskView(cardId = "") {
  const accepted = simulateAcceptTask(cardId);
  closeTaskView();
  return {
    cardId: accepted?.cardId || cardId,
    activeTaskStillExists: Boolean(state.activeTasks?.some((task) => task.cardId === (accepted?.cardId || cardId))),
    activeTaskExpanded: Boolean(state.activeTask?.expanded)
  };
}

function simulateCompleteTask(cardId = "") {
  const accepted = simulateAcceptTask(cardId);
  const beforePoints = getTotalPoints();
  if (state.currentCardSession) {
    state.currentCardSession.completionData = { text: "ok", choice: "ok", timerFinished: true };
    state.currentCardSession.completionDataIds = ["simulated"];
  }
  if (state.activeTask) {
    state.activeTask.completionType = state.activeTask.completionType || "confirm";
    if (["photo", "video", "audio"].includes(state.activeTask.completionType)) state.activeTask.mediaSent = true;
  }
  const taskId = state.activeTask?.id || "";
  completeTask(taskId);
  return {
    cardId: accepted?.cardId || cardId,
    removedFromActive: !state.activeTasks?.some((task) => task.id === taskId),
    archived: Boolean(state.taskArchive?.some((task) => task.id === taskId)),
    pointsChanged: getTotalPoints() - beforePoints
  };
}

function simulateExtendTask(cardId = "") {
  const accepted = simulateAcceptTask(cardId);
  const beforePoints = getTotalPoints();
  const beforeSteps = Array.isArray(state.activeTask?.steps) ? state.activeTask.steps.length : 0;
  extendTask(state.activeTask?.id || "");
  return {
    cardId: accepted?.cardId || cardId,
    stillActive: Boolean(state.activeTask),
    stepsDelta: (Array.isArray(state.activeTask?.steps) ? state.activeTask.steps.length : 0) - beforeSteps,
    pointsChanged: getTotalPoints() - beforePoints
  };
}

function simulateAbortTask(cardId = "") {
  const accepted = simulateAcceptTask(cardId);
  const beforePoints = getTotalPoints();
  const taskId = state.activeTask?.id || "";
  abortTask(taskId, "Simulation");
  return {
    cardId: accepted?.cardId || cardId,
    removedFromActive: !state.activeTasks?.some((task) => task.id === taskId),
    archivedAborted: Boolean(state.taskArchive?.some((task) => task.id === taskId && /abgebrochen/i.test(task.statusText || ""))),
    pointsChanged: getTotalPoints() - beforePoints
  };
}

function simulateLogoutPersistence() {
  const activeIds = (state.activeTasks || []).map((task) => task.id);
  const wishCounts = {
    mine: Array.isArray(state.secretWishes?.[state.activeIndex]) ? state.secretWishes[state.activeIndex].length : 0,
    total: Array.isArray(state.secretWishes?.flat?.()) ? state.secretWishes.flat().length : 0
  };
  saveState();
  loadState();
  syncActiveTasks();
  return {
    activeTasksRestored: activeIds.every((id) => state.activeTasks?.some((task) => task.id === id)),
    wishesRestored: wishCounts.total === (Array.isArray(state.secretWishes?.flat?.()) ? state.secretWishes.flat().length : 0)
  };
}

function validateShortGames() {
  const rows = truthOrDareCards.map((rawCard) => {
    const card = normalizeShortGameCard(rawCard);
    const mode = getShortGameModeConfig(card.mode);
    const context = {
      ...truthDareActorContext(),
      choice: card.gameType,
      modeId: card.mode,
      topic: inferCardTopic(card),
      maxAllowedIntensity: mode.maxIntensity
    };
    const issues = [];
    if (!String(card.id || "").trim()) issues.push("missing-id");
    if (!String(card.title || "").trim()) issues.push("missing-title");
    if (!String(card.text || "").trim()) issues.push("missing-text");
    if (!String(card.gameType || "").trim()) issues.push("missing-gameType");
    if (!String(card.type || "").trim()) issues.push("missing-type");
    if (!String(card.mode || "").trim()) issues.push("missing-mode");
    if (!Number.isFinite(Number(card.intensity))) issues.push("missing-intensity");
    if (!CARD_COMPLETION_TYPES.has(card.completionType)) issues.push("invalid-completionType");
    if (card.gameType === "truth" && !String(card.answerRule || "").trim()) issues.push("missing-answerRule");
    if (card.completionType === "choice" && !(card.choices || []).length) issues.push("choice-without-choices");
    if (card.completionType === "timer" && !Number(card.duration || card.durationMinutes || 0)) issues.push("timer-without-duration");
    if (["photo", "video", "audio"].includes(card.completionType) && (!card.saveToLibrary || !card.libraryCategory)) issues.push("media-without-library-target");
    if (!truthCardMatchesMode(card, card.mode)) issues.push("mode-mismatch");
    if (!isCardPlayable(card, context)) issues.push("unplayable");
    if (card.mode === "intense" && !card.requiresBothConsent) issues.push("intense-without-consent");
    if ((card.mode === "intro" || card.mode === "playful") && card.intensity > getShortGameModeConfig(card.mode).maxIntensity) issues.push("too-hard-for-mode");
    if ((card.mode === "direct" || card.mode === "intense") && card.intensity < getShortGameModeConfig(card.mode).minIntensity) issues.push("too-soft-for-mode");
    return {
      id: card.id || "",
      title: card.title || "",
      gameType: card.gameType || "",
      type: card.type || "",
      mode: card.mode || "",
      intensity: card.intensity || 0,
      completionType: card.completionType || "",
      status: issues.length ? "needs-review" : "ok",
      issues: issues.join(", ")
    };
  });
  console.table(rows);
  return rows;
}

function validateShortGameModes() {
  const context = truthDareActorContext();
  const rows = getAvailableShortGameModes(context).map((mode) => ({
    id: mode.id || "",
    label: mode.label || "",
    available: mode.available ? "yes" : "no",
    availableCount: Number.isFinite(mode.availableCount) ? mode.availableCount : 0
  }));
  console.table(rows);
  return rows;
}

function simulateAbortCard(cardId) {
  const source = allCardSources().find((card) => card.id === cardId) || allCardSources()[0];
  if (!source) return null;
  const snapshot = {
    currentCardSession: state.currentCardSession ? { ...state.currentCardSession } : null,
    cardSessions: Array.isArray(state.cardSessions) ? state.cardSessions.map((entry) => ({ ...entry })) : [],
    cardCategory: elements.cardCategory?.textContent || "",
    cardTitle: elements.cardTitle?.textContent || "",
    cardText: elements.cardText?.textContent || "",
    panel: document.querySelector("#cardCompletionPanel")?.innerHTML || "",
    drawHidden: Boolean(elements.drawCard?.hidden),
    completeHidden: Boolean(elements.completeCard?.hidden),
    skipHidden: Boolean(elements.skipCard?.hidden)
  };
  const context = buildCardDrawContext({ modeId: source.mode, topic: source.topic });
  const session = buildCardSession(source, context);
  renderCardPreview(source, session);
  finaliseCardSession(session, "aborted");
  const row = {
    id: source.id,
    title: source.title,
    type: source.type,
    completionType: normalizeCardCompletion(source).completionType,
    status: "simulated-aborted",
    sessionId: session.sessionId
  };
  console.table([row]);
  state.currentCardSession = snapshot.currentCardSession;
  state.cardSessions = snapshot.cardSessions;
  if (snapshot.currentCardSession?.card) {
    renderCardPreview(snapshot.currentCardSession.card, snapshot.currentCardSession);
  } else {
    elements.cardCategory.textContent = snapshot.cardCategory || "Bereit?";
    elements.cardTitle.textContent = snapshot.cardTitle || "Bereit";
    elements.cardText.textContent = snapshot.cardText || "Ich delegiere. Ihr entscheidet nur, ob ihr es macht.";
    clearCardCompletionPanel();
    updateCardActionState("idle");
  }
  if (document.querySelector("#cardCompletionPanel")) {
    document.querySelector("#cardCompletionPanel").innerHTML = snapshot.panel || "";
  }
  if (elements.drawCard) elements.drawCard.hidden = snapshot.drawHidden;
  if (elements.completeCard) elements.completeCard.hidden = snapshot.completeHidden;
  if (elements.skipCard) elements.skipCard.hidden = snapshot.skipHidden;
  saveState();
  return row;
}

function simulateCardPlaythrough(cardId) {
  const source = allCardSources().find((card) => card.id === cardId) || allCardSources()[0];
  if (!source) return null;
  const snapshot = {
    currentCardSession: state.currentCardSession ? { ...state.currentCardSession } : null,
    cardSessions: Array.isArray(state.cardSessions) ? state.cardSessions.map((entry) => ({ ...entry })) : [],
    cardCategory: elements.cardCategory?.textContent || "",
    cardTitle: elements.cardTitle?.textContent || "",
    cardText: elements.cardText?.textContent || "",
    panel: document.querySelector("#cardCompletionPanel")?.innerHTML || "",
    drawHidden: Boolean(elements.drawCard?.hidden),
    completeHidden: Boolean(elements.completeCard?.hidden),
    skipHidden: Boolean(elements.skipCard?.hidden)
  };
  const context = buildCardDrawContext({ modeId: source.mode, topic: source.topic });
  const session = buildCardSession(source, context);
  renderCardPreview(source, session);
  session.status = "accepted";
  session.acceptedAt = new Date().toISOString();
  renderCardCompletion(source, session);
  const completionType = normalizeCardCompletion(source).completionType;
  if (completionType === "text") session.completionData = { ...(session.completionData || {}), text: "Dummy-Antwort" };
  if (completionType === "choice") session.completionData = { ...(session.completionData || {}), choice: (normalizeCardCompletion(source).choices[0] || "choice-1") };
  if (completionType === "timer") session.completionData = { ...(session.completionData || {}), timerState: { running: false, startedAt: "", elapsedMs: 30000 } };
  if (["photo", "video", "audio"].includes(completionType)) {
    const dummyId = `dummy-${completionType}-${Date.now()}`;
    session.completionData = { ...(session.completionData || {}), mediaIds: [dummyId], mediaSaved: true };
    session.completionDataIds = [dummyId];
  }
  finaliseCardSession(session, "completed");
  const row = {
    id: source.id,
    title: source.title,
    type: source.type,
    completionType,
    status: "simulated-completed",
    sessionId: session.sessionId
  };
  console.table([row]);
  state.currentCardSession = snapshot.currentCardSession;
  state.cardSessions = snapshot.cardSessions;
  if (snapshot.currentCardSession?.card) {
    renderCardPreview(snapshot.currentCardSession.card, snapshot.currentCardSession);
  } else {
    elements.cardCategory.textContent = snapshot.cardCategory || "Bereit?";
    elements.cardTitle.textContent = snapshot.cardTitle || "Bereit";
    elements.cardText.textContent = snapshot.cardText || "Ich delegiere. Ihr entscheidet nur, ob ihr es macht.";
    clearCardCompletionPanel();
    updateCardActionState("idle");
  }
  if (document.querySelector("#cardCompletionPanel")) {
    document.querySelector("#cardCompletionPanel").innerHTML = snapshot.panel || "";
  }
  if (elements.drawCard) elements.drawCard.hidden = snapshot.drawHidden;
  if (elements.completeCard) elements.completeCard.hidden = snapshot.completeHidden;
  if (elements.skipCard) elements.skipCard.hidden = snapshot.skipHidden;
  saveState();
  return row;
}

function simulateAllCardPlaythroughs() {
  const rows = allCardSources().map((card) => simulateCardPlaythrough(card.id)).filter(Boolean);
  console.table(rows);
  return rows;
}
