function normalizeProfile(profile = {}) {
  return {
    about: profile.about || "",
    questions: profile.questions || "",
    avatarData: profile.avatarData || "",
    answers: profile.answers && typeof profile.answers === "object" ? profile.answers : {},
    hiddenAnswers: profile.hiddenAnswers && typeof profile.hiddenAnswers === "object" ? profile.hiddenAnswers : {},
    tryRanking: normalizeTryRanking(profile.tryRanking),
    interestPerspective: normalizeInterestPerspective(profile.interestPerspective),
    setupComplete: Boolean(profile.setupComplete)
  };
}

function normalizeInterestPerspective(perspective = {}) {
  const result = {};
  const allowedStatuses = new Set(["likes", "curious", "neutral", "not_for_me", "taboo"]);
  const allowedVisibility = new Set(["private", "match", "shared"]);
  if (!perspective || typeof perspective !== "object") return result;
  Object.entries(perspective).forEach(([topicId, rawValue]) => {
    const value = rawValue && typeof rawValue === "object" ? rawValue : {};
    const key = normalizeCardTopic(topicId);
    if (!key) return;
    result[key] = {
      selfInterest: Math.max(0, Math.min(5, Number(value.selfInterest) || 0)),
      enjoysPartnerInterest: Math.max(0, Math.min(5, Number(value.enjoysPartnerInterest) || 0)),
      comfortBeingFocus: Math.max(0, Math.min(5, Number(value.comfortBeingFocus) || 0)),
      comfortGivingFocus: Math.max(0, Math.min(5, Number(value.comfortGivingFocus) || 0)),
      maxIntensity: Math.max(1, Math.min(5, Number(value.maxIntensity) || 1)),
      visibility: allowedVisibility.has(value.visibility) ? value.visibility : "private",
      status: allowedStatuses.has(value.status) ? value.status : "neutral"
    };
  });
  return result;
}

function normalizeTryRanking(value = []) {
  const saved = new Map();
  if (Array.isArray(value)) {
    value.forEach((item, index) => {
      if (!item || !item.id) return;
      const oldRank = Number(item.rank) || index + 1;
      const migratedRating = typeof item.rating === "number"
        ? Math.max(0, Math.min(3, Math.round(item.rating)))
        : item.checked
          ? oldRank <= 5 ? 3 : oldRank <= 15 ? 2 : 1
          : 0;
      saved.set(item.id, {
        id: item.id,
        label: item.label || item.id,
        tags: Array.isArray(item.tags) ? item.tags : [],
        description: item.description || tryRankingDescriptions[item.id] || "",
        rating: migratedRating
      });
    });
  }

  const merged = defaultTryRankingItems.map((item) => {
    const existing = saved.get(item.id);
    return {
      id: item.id,
      label: item.label,
      tags: item.tags || [],
      description: item.description || tryRankingDescriptions[item.id] || "",
      rating: Number(existing?.rating) || 0
    };
  });

  saved.forEach((item) => {
    if (!merged.some((entry) => entry.id === item.id)) merged.push(item);
  });

  return merged;
}

function profileHasAnswers(index) {
  const answers = state.profiles[index]?.answers || {};
  return activeProfileQuestions(index).some((question) => (answers[question.id] || "").trim());
}

function normalizeProfileQuestionSettings() {
  const knownIds = new Set(profileQuestions.map((question) => question.id));
  const enabled = Array.isArray(state.profileQuestionSettings?.enabled)
    ? state.profileQuestionSettings.enabled.filter((id) => knownIds.has(id))
    : profileQuestions.map((question) => question.id);
  state.profileQuestionSettings = {
    enabled: enabled.length ? [...new Set(enabled)] : profileQuestions.map((question) => question.id)
  };
  return state.profileQuestionSettings;
}

function profileQuestionAudience(questionId) {
  const jennyOnly = new Set([
    "jennyFeetChristianFeeling",
    "pleasureMap",
    "jennyOralTruth",
    "squirtingCuriosity"
  ]);
  const christianOnly = new Set([
    "partnerSecretWish"
  ]);
  if (jennyOnly.has(questionId)) return "jenny";
  if (christianOnly.has(questionId)) return "christian";
  return "both";
}

function profileQuestionMatchesProfile(question, profileIndex) {
  const audience = profileQuestionAudience(question.id);
  if (audience === "jenny") return Number(profileIndex) === 1;
  if (audience === "christian") return Number(profileIndex) === 0;
  return true;
}

function activeProfileQuestions(profileIndex = null) {
  const enabled = new Set(normalizeProfileQuestionSettings().enabled);
  return profileQuestions.filter((question) => {
    if (!enabled.has(question.id)) return false;
    if (profileIndex === null || typeof profileIndex === "undefined") return true;
    return profileQuestionMatchesProfile(question, profileIndex);
  });
}

function profileQuestionPartnerName(profileIndex) {
  const index = Number(profileIndex) === 0 ? 1 : 0;
  return state.players[index] || (index === 0 ? "Christian" : "Jenny");
}

function profileQuestionLabel(question, profileIndex) {
  if (question.id === "partnerFantasy") {
    return `Welche Fantasie hast du mit ${profileQuestionPartnerName(profileIndex)}?`;
  }
  if (question.id === "partnerSecretWish") {
    return "Was glaubst du, wuenscht sich Jenny heimlich?";
  }
  return question.label;
}

function profileQuestionPlaceholder(question, profileIndex) {
  if (question.id === "partnerFantasy") {
    return `Was soll ${profileQuestionPartnerName(profileIndex)} tun, sagen, zeigen oder zulassen?`;
  }
  if (question.id === "partnerSecretWish") {
    return "Eine Vermutung ueber Jenny, die We2 vorsichtig testen darf.";
  }
  return question.placeholder;
}

function prepareComfortTextarea(textarea) {
  if (!textarea) return;
  textarea.spellcheck = true;
  textarea.autocomplete = "on";
  textarea.setAttribute("autocorrect", "on");
  textarea.setAttribute("autocapitalize", "sentences");
  textarea.setAttribute("inputmode", "text");
  textarea.addEventListener("input", () => {
    textarea.style.height = "auto";
    textarea.style.height = `${Math.max(84, textarea.scrollHeight)}px`;
  });
  window.setTimeout(() => {
    textarea.style.height = "auto";
    textarea.style.height = `${Math.max(84, textarea.scrollHeight)}px`;
  }, 0);
}

function renderQuestionFields(container, profileIndex, prefix) {
  if (!container) return;
  container.innerHTML = "";
  const profile = normalizeProfile(state.profiles[profileIndex]);
  const answers = profile.answers || {};
  const hiddenAnswers = profile.hiddenAnswers || {};

  activeProfileQuestions(profileIndex).forEach((question) => {
    const label = document.createElement("label");
    const textarea = document.createElement("textarea");
    const privacy = document.createElement("div");
    const checkbox = document.createElement("input");
    const privacyText = document.createElement("span");
    textarea.rows = 2;
    textarea.id = `${prefix}-${question.id}`;
    textarea.dataset.questionId = question.id;
    textarea.placeholder = profileQuestionPlaceholder(question, profileIndex);
    textarea.value = answers[question.id] || "";
    prepareComfortTextarea(textarea);
    textarea.addEventListener("input", markProfilesDirty);
    checkbox.type = "checkbox";
    checkbox.dataset.privateQuestionId = question.id;
    checkbox.checked = Boolean(hiddenAnswers[question.id]);
    checkbox.addEventListener("change", markProfilesDirty);
    privacy.className = "question-private-toggle";
    privacyText.textContent = "Vor Partner ausblenden";
    label.textContent = profileQuestionLabel(question, profileIndex);
    label.append(textarea);
    privacy.append(checkbox, privacyText);
    label.append(privacy);
    container.append(label);
  });
}

function readQuestionFields(container) {
  const answers = {};
  const hiddenAnswers = {};
  if (!container) return { answers, hiddenAnswers };
  container.querySelectorAll("textarea[data-question-id]").forEach((field) => {
    answers[field.dataset.questionId] = field.value.trim();
  });
  container.querySelectorAll("input[data-private-question-id]").forEach((field) => {
    if (field.checked) hiddenAnswers[field.dataset.privateQuestionId] = true;
  });
  return { answers, hiddenAnswers };
}

function sectionForRankingContainer(container) {
  if (!container) return null;
  return container.closest(".try-ranking-section");
}

function renderTryRanking(container, profileIndex, prefix) {
  if (!container) return;
  const section = sectionForRankingContainer(container);
  const items = normalizeTryRanking(state.profiles[profileIndex]?.tryRanking || []);
  container.innerHTML = "";
  if (section) section.hidden = !items.length;
  if (!items.length) return;

  items.forEach((item, index) => {
    const row = document.createElement("article");
    const meta = document.createElement("small");
    const title = document.createElement("span");
    const infoDetails = document.createElement("details");
    const infoSummary = document.createElement("summary");
    const infoText = document.createElement("p");
    const buttons = document.createElement("div");

    row.className = "try-ranking-item";
    row.dataset.rankingId = item.id;
    row.dataset.rankingLabel = item.label;
    row.dataset.rating = String(Number(item.rating) || 0);
    meta.textContent = rankingGroupLabel(item.tags || []);

    title.className = "try-ranking-title";
    title.textContent = item.label;

    infoDetails.className = "try-info";
    infoSummary.textContent = "Was ist das?";
    infoSummary.setAttribute("role", "button");
    infoText.id = `${prefix}-${item.id}-info`;
    infoText.className = "try-info-text";
    infoText.textContent = item.description || "Kurze Erklaerung folgt.";
    infoDetails.append(infoSummary, infoText);

    buttons.className = "try-rating-buttons";
    [
      { value: 0, label: "Nein" },
      { value: 1, label: "1 Stern" },
      { value: 2, label: "2 Sterne" },
      { value: 3, label: "3 Sterne" }
    ].forEach((option) => {
      const button = document.createElement("button");
      button.type = "button";
      button.textContent = option.label;
      button.dataset.tryRating = String(option.value);
      button.className = Number(item.rating) === option.value ? "primary" : "";
      button.addEventListener("click", () => {
        row.dataset.rating = String(option.value);
        [...buttons.querySelectorAll("button")].forEach((ratingButton) => {
          ratingButton.classList.toggle("primary", ratingButton === button);
        });
        markProfilesDirty();
      });
      buttons.append(button);
    });

    row.append(meta, title, infoDetails, buttons);
    container.append(row);
  });
}

function rankingGroupLabel(tags = []) {
  if (tags.includes("toy")) return "Toy";
  if (tags.includes("bondage") || tags.includes("control") || tags.includes("dominance")) return "Macht";
  if (tags.includes("sensation") || tags.includes("mirror") || tags.includes("voice")) return "Sinne";
  if (tags.includes("oral") || tags.includes("anal") || tags.includes("position") || tags.includes("hand")) return "Praktik";
  return "Thema";
}

function readTryRanking(container) {
  if (!container) return null;
  const rows = [...container.querySelectorAll("[data-ranking-id]")];
  if (!rows.length) return null;
  return rows
    .map((row) => {
      const id = row.dataset.rankingId;
      return {
        id,
        label: row.dataset.rankingLabel || id,
        tags: defaultTryRankingItems.find((item) => item.id === id)?.tags || [],
        description: tryRankingDescriptions[id] || "",
        rating: Math.max(0, Math.min(3, Number(row.dataset.rating) || 0))
      };
    });
}

function shouldOpenProfileSetup(index) {
  return !state.profiles[index].setupComplete;
}

function normalizeProfileArray(value, fallback = {}) {
  const first = value?.[0] && typeof value[0] === "object" ? value[0] : fallback;
  const second = value?.[1] && typeof value[1] === "object" ? value[1] : {};
  return [{ ...first }, { ...second }];
}

function activeRuleMemory() {
  state.seenRulesByProfile = normalizeProfileArray(state.seenRulesByProfile);
  return state.seenRulesByProfile[state.activeIndex] || {};
}

function hasSeenCategoryRule(categoryId) {
  const memory = activeRuleMemory();
  return Boolean(memory[categoryId]);
}

function markCategoryRuleSeen(categoryId) {
  state.seenRulesByProfile = normalizeProfileArray(state.seenRulesByProfile);
  state.seenRulesByProfile[state.activeIndex][categoryId] = true;
  state.seenRules[categoryId] = true;
}

function renderProfileQuestionEditors() {
  renderQuestionFields(elements.profileAnswersOne, 0, "profile-one");
  renderQuestionFields(elements.profileAnswersTwo, 1, "profile-two");
  renderTryRanking(elements.profileTryRankingOne, 0, "profile-ranking-one");
  renderTryRanking(elements.profileTryRankingTwo, 1, "profile-ranking-two");
}

function renderProfileQuestionControls() {
  if (!elements.profileQuestionControls) return;
  const enabled = new Set(normalizeProfileQuestionSettings().enabled);
  elements.profileQuestionControls.innerHTML = "";

  profileQuestions.forEach((question) => {
    const row = document.createElement("label");
    const checkbox = document.createElement("input");
    const text = document.createElement("span");
    const badge = document.createElement("small");
    const audience = profileQuestionAudience(question.id);
    row.className = "profile-question-control";
    checkbox.type = "checkbox";
    checkbox.dataset.profileQuestionId = question.id;
    checkbox.checked = enabled.has(question.id);
    checkbox.addEventListener("change", () => {
      if (elements.profileStatus) elements.profileStatus.textContent = "Fragen geaendert, noch nicht gespeichert.";
    });
    text.textContent = question.label;
    badge.textContent = audience === "jenny" ? "Jenny" : audience === "christian" ? "Christian" : "Beide";
    row.append(checkbox, text, badge);
    elements.profileQuestionControls.append(row);
  });
}

function saveProfileQuestionControls() {
  if (!elements.profileQuestionControls) return;
  const enabled = [...elements.profileQuestionControls.querySelectorAll("input[data-profile-question-id]:checked")]
    .map((input) => input.dataset.profileQuestionId)
    .filter(Boolean);
  state.profileQuestionSettings = {
    enabled: enabled.length ? enabled : profileQuestions.map((question) => question.id)
  };
  saveState();
  renderProfileQuestionControls();
  if (!elements.profileView.hidden) renderSelfProfile();
  if (elements.profileStatus) elements.profileStatus.textContent = "Fragen gespeichert.";
}

function normalizePopupSettings() {
  const saved = state.popupSettings && typeof state.popupSettings === "object" ? state.popupSettings : {};
  state.popupSettings = {
    welcome: Boolean(saved.welcome),
    loginNews: typeof saved.loginNews === "boolean" ? saved.loginNews : true
  };
  return state.popupSettings;
}

function normalizeTimeInput(value, fallback) {
  return /^([01]\d|2[0-3]):[0-5]\d$/.test(String(value || "")) ? String(value) : fallback;
}

function normalizeCustomPopup(popup) {
  const interval = Math.max(1, Math.min(99, Number(popup?.interval) || 5));
  const shownAtOpen = Array.isArray(popup?.shownAtOpen) ? popup.shownAtOpen : [0, 0];
  return {
    id: popup?.id || `popup-${Date.now()}-${Math.random().toString(36).slice(2)}`,
    title: String(popup?.title || "We2").trim() || "We2",
    text: String(popup?.text || "").trim(),
    interval,
    active: popup?.active !== false,
    createdAt: popup?.createdAt || new Date().toISOString(),
    shownAtOpen: [
      Number(shownAtOpen[0]) || 0,
      Number(shownAtOpen[1]) || 0
    ]
  };
}

function normalizeCustomPopups() {
  if (!Array.isArray(state.customPopups)) state.customPopups = [];
  state.customPopups = state.customPopups
    .map(normalizeCustomPopup)
    .filter((popup) => popup.text)
    .slice(-30);
  return state.customPopups;
}

function renderCustomPopupSettings() {
  normalizeCustomPopups();
  if (!elements.customPopupList) return;
  elements.customPopupList.innerHTML = "";
  if (!state.customPopups.length) {
    const empty = document.createElement("p");
    empty.textContent = "Noch kein eigenes Popup geplant.";
    elements.customPopupList.append(empty);
    return;
  }
  state.customPopups.slice().reverse().forEach((popup) => {
    const item = document.createElement("article");
    const title = document.createElement("strong");
    const meta = document.createElement("small");
    const text = document.createElement("p");
    const toggle = document.createElement("button");
    const remove = document.createElement("button");
    title.textContent = popup.title;
    meta.textContent = `${popup.active ? "aktiv" : "pausiert"} Â· jedes ${popup.interval}. Ã–ffnen`;
    text.textContent = popup.text;
    toggle.type = "button";
    toggle.textContent = popup.active ? "Pausieren" : "Aktivieren";
    toggle.addEventListener("click", () => {
      popup.active = !popup.active;
      saveState();
      renderCustomPopupSettings();
    });
    remove.type = "button";
    remove.textContent = "LÃ¶schen";
    remove.addEventListener("click", () => {
      state.customPopups = state.customPopups.filter((itemPopup) => itemPopup.id !== popup.id);
      saveState();
      renderCustomPopupSettings();
    });
    item.append(title, meta, text, toggle, remove);
    elements.customPopupList.append(item);
  });
}

function renderPopupSettings() {
  const settings = normalizePopupSettings();
  if (elements.settingWelcomePopups) elements.settingWelcomePopups.checked = Boolean(settings.welcome);
  if (elements.settingLoginNews) elements.settingLoginNews.checked = Boolean(settings.loginNews);
  renderCustomPopupSettings();
}

function savePopupSettings() {
  state.popupSettings = {
    welcome: Boolean(elements.settingWelcomePopups?.checked),
    loginNews: Boolean(elements.settingLoginNews?.checked)
  };
  if (!state.popupSettings.welcome) {
    state.welcomeSeen = [true, true];
    state.welcomeSeenVersion = [welcomeTextVersion, welcomeTextVersion];
    if (elements.welcomeModal) elements.welcomeModal.hidden = true;
  }
  if (!state.popupSettings.loginNews && elements.loginNewsModal) elements.loginNewsModal.hidden = true;
  saveState();
  renderPopupSettings();
  if (elements.popupSettingsStatus) elements.popupSettingsStatus.textContent = "Popups gespeichert.";
}

function addCustomPopupSetting() {
  const text = elements.customPopupText?.value.trim() || "";
  if (!text) {
    if (elements.popupSettingsStatus) elements.popupSettingsStatus.textContent = "Bitte erst einen Popup-Text schreiben.";
    return;
  }
  normalizeCustomPopups();
  state.customPopups.push(normalizeCustomPopup({
    title: elements.customPopupTitle?.value || "We2",
    text,
    interval: elements.customPopupInterval?.value || 5,
    active: elements.customPopupActive?.checked !== false
  }));
  if (elements.customPopupTitle) elements.customPopupTitle.value = "";
  if (elements.customPopupText) elements.customPopupText.value = "";
  if (elements.customPopupInterval) elements.customPopupInterval.value = "5";
  if (elements.customPopupActive) elements.customPopupActive.checked = true;
  saveState();
  renderPopupSettings();
  if (elements.popupSettingsStatus) elements.popupSettingsStatus.textContent = "Popup hinzugefÃ¼gt.";
}

