function insertDashboardChatEmoji(emoji) {
  if (!elements.dashboardChatInput || !emoji) return;
  const input = elements.dashboardChatInput;
  const start = Number(input.selectionStart) || input.value.length;
  const end = Number(input.selectionEnd) || input.value.length;
  const prefix = input.value.slice(0, start);
  const suffix = input.value.slice(end);
  const spacer = prefix && !/\s$/.test(prefix) ? " " : "";
  input.value = `${prefix}${spacer}${emoji}${suffix}`;
  const cursor = `${prefix}${spacer}${emoji}`.length;
  input.focus();
  input.setSelectionRange(cursor, cursor);
}

function reactToDashboardChat(messageId, emoji) {
  if (!Array.isArray(state.sharedChat)) return;
  const message = state.sharedChat.find((item) => item?.id === messageId);
  if (!message) return;
  if (!message.reactions || typeof message.reactions !== "object") message.reactions = {};
  const key = String(state.activeIndex);
  message.reactions[key] = message.reactions[key] === emoji ? "" : emoji;
  saveState();
  renderDashboardChat();
  void 0;
}

function deleteDashboardChatMessage(messageId) {
  if (!Array.isArray(state.sharedChat)) return;
  state.sharedChat = state.sharedChat.filter((message) => message?.id !== messageId);
  saveState();
  renderDashboardChat();
  updateLabels();
}

function submitDashboardChat(event) {
  event.preventDefault();
  const text = elements.dashboardChatInput?.value.trim() || "";
  if (!text) return;
  if (!Array.isArray(state.sharedChat)) state.sharedChat = [];
  state.sharedChat.push({
    id: `chat-${Date.now()}-${Math.random().toString(36).slice(2)}`,
    player: state.activeIndex,
    text,
    at: new Date().toISOString(),
    reactions: {}
  });
  state.sharedChat = state.sharedChat.slice(-120);
  if (elements.dashboardChatInput) elements.dashboardChatInput.value = "";
  saveState();
  renderDashboardChat();
  updateLabels();
}

function secretWishItems(playerIndex = null) {
  if (!Array.isArray(state.secretWishes)) state.secretWishes = [];
  return state.secretWishes.filter((wish) => {
    if (!wish || !String(wish.text || "").trim()) return false;
    return playerIndex === null || Number(wish.player) === Number(playerIndex);
  });
}

function renderDashboardWishBox() {
  if (!elements.dashboardWishBoxList) return;
  const wishes = secretWishItems();
  const christianWishes = secretWishItems(0);
  const jennyWishes = secretWishItems(1);
  elements.dashboardWishBoxList.innerHTML = "";
  if (elements.dashboardWishBoxCount) elements.dashboardWishBoxCount.textContent = `${christianWishes.length}/${jennyWishes.length}`;
  if (elements.drawDashboardWish) {
    const ownWishes = secretWishItems(state.activeIndex);
    elements.drawDashboardWish.disabled = !ownWishes.length;
    elements.drawDashboardWish.textContent = `Wunsch von ${state.players[state.activeIndex]} ziehen`;
  }
  if (!wishes.length) {
    const empty = document.createElement("p");
    empty.className = "dashboard-panel-empty";
    empty.textContent = "Noch kein Wunsch in der Box.";
    elements.dashboardWishBoxList.append(empty);
    return;
  }
  [0, 1].forEach((playerIndex) => {
    const groupWishes = secretWishItems(playerIndex);
    const group = document.createElement("section");
    const title = document.createElement("h4");
    group.className = "wish-owner-group";
    title.textContent = `${state.players[playerIndex]} (${groupWishes.length})`;
    group.append(title);
    if (!groupWishes.length) {
      const empty = document.createElement("p");
      empty.className = "dashboard-panel-empty";
      empty.textContent = "Noch leer.";
      group.append(empty);
    }
    groupWishes.slice().reverse().slice(0, 12).forEach((wish) => {
      const item = document.createElement("article");
      const meta = document.createElement("small");
      const text = document.createElement("p");
      const draws = Number(wish.drawnCount) || 0;
      meta.textContent = [
        wish.mood || "Wunsch",
        draws ? `${draws}x gezogen` : "neu",
        formatTaskDateTime(wish.createdAt)
      ].filter(Boolean).join(" Â· ");
      text.textContent = wish.text || "";
      item.append(meta, text);
      group.append(item);
    });
    elements.dashboardWishBoxList.append(group);
  });
  return;
  elements.dashboardWishBoxList.innerHTML = "";
  if (elements.dashboardWishBoxCount) elements.dashboardWishBoxCount.textContent = String(wishes.length);
  if (elements.drawDashboardWish) elements.drawDashboardWish.disabled = !wishes.length;
  if (!wishes.length) {
    const empty = document.createElement("p");
    empty.className = "dashboard-panel-empty";
    empty.textContent = "Noch kein Wunsch in der Box.";
    elements.dashboardWishBoxList.append(empty);
    return;
  }
  wishes.slice().reverse().slice(0, 20).forEach((wish) => {
    const item = document.createElement("article");
    const meta = document.createElement("small");
    const text = document.createElement("p");
    const draws = Number(wish.drawnCount) || 0;
    meta.textContent = [
      state.players[wish.player] || "We2",
      wish.mood || "Wunsch",
      draws ? `${draws}x gezogen` : "neu",
      formatTaskDateTime(wish.createdAt)
    ].filter(Boolean).join(" Â· ");
    text.textContent = wish.text || "";
    item.append(meta, text);
    elements.dashboardWishBoxList.append(item);
  });
}

