function pickSecretWishFromPool(wishes) {
  if (!wishes.length) return null;
  const leastDrawn = Math.min(...wishes.map((wish) => Number(wish.drawnCount) || 0));
  const pool = wishes.filter((wish) => (Number(wish.drawnCount) || 0) === leastDrawn);
  return pool[Math.floor(Math.random() * pool.length)] || wishes[0];
}

function createWishTaskFromWish(wish, options = {}) {
  if (!wish) return null;
  wish.drawnCount = (Number(wish.drawnCount) || 0) + 1;
  wish.lastDrawnAt = new Date().toISOString();
  const author = state.players[wish.player] || "We2";
  const now = new Date().toISOString();
  const task = {
    id: `wishbox-task-${Date.now()}-${Math.random().toString(36).slice(2)}`,
    categoryId: "wish-box",
    categoryTitle: "WÃ¼nsche-Box",
    title: "Geheimer Wunsch",
    text: wish.text,
    steps: [],
    tags: ["talk", "wish"],
    drawnBy: options.drawnBy || "We2 zieht aus der WÃ¼nsche-Box",
    roleLine: `Wunsch von ${author}. Sprecht kurz Grenze, Zeitpunkt und wie ihr ihn spielen wollt.`,
    hideRoleLine: false,
    starter: Number.isInteger(options.starter) ? options.starter : state.activeIndex,
    visible: true,
    secretForPartner: false,
    status: "active",
    expanded: Boolean(options.open),
    pointValue: wish.mood === "mutig" ? 25 : wish.mood === "direkt" ? 20 : 15,
    moreCount: 0,
    pointLabel: "Wunsch gespielt",
    pointsForBoth: true,
    pointsAwarded: false,
    mediaSent: false,
    startedAt: now,
    comments: [
      {
        type: "system",
        player: Number.isInteger(options.starter) ? options.starter : state.activeIndex,
        text: options.comment || `We2 hat einen Wunsch von ${author} gezogen.`,
        at: now
      }
    ],
    wishBoxId: wish.id
  };
  syncActiveTasks();
  if (!Array.isArray(state.activeTasks)) state.activeTasks = [];
  state.activeTasks.unshift(task);
  state.activeTasks.forEach((item) => {
    if (item.id !== task.id) item.expanded = false;
  });
  state.activeTask = options.open ? task : null;
  return task;
}

function drawWishForPlayer(playerIndex, options = {}) {
  const wishes = secretWishItems(playerIndex);
  const wish = pickSecretWishFromPool(wishes);
  if (!wish) return null;
  const task = createWishTaskFromWish(wish, options);
  if (options.open) {
    dashboardWishBoxOpen = false;
    dashboardTaskListOpen = true;
    if (elements.dashboardWishBoxPanel) elements.dashboardWishBoxPanel.hidden = true;
    renderTaskThread();
  }
  saveState();
  renderDashboardWishBox();
  updateLabels();
  return task;
}

function runScheduledWeeklyWishDraw(now = new Date()) {
  if (!weeklyWishDrawDue(now) || document.body.classList.contains("locked")) return false;
  const draws = normalizeWeeklyWishDraws();
  const key = weekKey(now);
  if (draws[key]) return false;
  const winner = weeklyWishWinnerIndex();
  if (winner === null) {
    draws[key] = {
      status: "tie",
      drawnAt: now.toISOString(),
      scores: currentWeekScore().scores || [0, 0]
    };
    saveState();
    return false;
  }
  const wish = pickSecretWishFromPool(secretWishItems(winner));
  if (!wish) {
    draws[key] = {
      status: "empty",
      winner,
      drawnAt: now.toISOString(),
      scores: currentWeekScore().scores || [0, 0]
    };
    saveState();
    return false;
  }
  const winnerName = state.players[winner] || "We2";
  draws[key] = {
    status: "drawing",
    winner,
    wishId: wish.id,
    drawnAt: now.toISOString(),
    scores: currentWeekScore().scores || [0, 0]
  };
  const task = createWishTaskFromWish(wish, {
    open: false,
    starter: winner,
    drawnBy: `Wunsch-Duell: ${winnerName} gewinnt die Woche`,
    comment: `Sonntag 19:00: ${winnerName} gewinnt das Wunsch-Duell. We2 zieht einen Wunsch aus ${winnerName}s Box.`
  });
  draws[key] = {
    ...draws[key],
    status: "drawn",
    taskId: task?.id || ""
  };
  saveState();
  renderDashboardWishBox();
  return true;
}

