function profileWords() {
  const answerText = state.profiles
    .map((profile) => Object.values(profile.answers || {}).join(" "))
    .join(" ");
  const rankingText = state.profiles
    .flatMap((profile) => normalizeTryRanking(profile.tryRanking || []))
    .filter((item) => Number(item.rating) > 0)
    .map((item) => `${item.label} ${(item.tags || []).join(" ")}`.repeat(Number(item.rating) || 1))
    .join(" ");
  return `${state.likesOne} ${state.likesTwo} ${state.profiles[0]?.about || ""} ${state.profiles[1]?.about || ""} ${answerText} ${rankingText}`.toLowerCase();
}

function rankingPreferenceScore(tags = []) {
  let score = 0;
  state.profiles
    .flatMap((profile) => normalizeTryRanking(profile.tryRanking || []))
    .filter((item) => Number(item.rating) > 0)
    .forEach((item) => {
      const itemTags = item.tags || [];
      const rating = Math.max(1, Math.min(3, Number(item.rating) || 0));
      const match = tags.some((tag) => itemTags.includes(tag) || String(item.label || "").toLowerCase().includes(tag));
      if (match) score += rating * 3;
    });
  return score;
}

