function isSoloAnalTask(task = {}) {
  const tags = task.tags || [];
  const rawText = typeof task.text === "function" ? "" : task.text || "";
  const lower = `${task.id || ""} ${task.title || ""} ${rawText}`.toLowerCase();
  return tags.includes("solo") && (
    tags.includes("anal") ||
    tags.includes("prostate") ||
    /anal|prostata|plug/.test(lower)
  );
}

function soloAnalAllowed() {
  if (!state.gameSettings?.anal) return false;
  const history = Array.isArray(state.soloAnalHistory) ? state.soloAnalHistory : [];
  const normalSinceAnal = [...history].reverse().findIndex((entry) => entry === "anal");
  const normalCount = normalSinceAnal === -1 ? history.length : normalSinceAnal;
  if (normalCount < 8) return false;
  return !history.slice(-12).includes("anal");
}

function balanceSoloAnalPool(pool = []) {
  const analTasks = pool.filter(isSoloAnalTask);
  if (!analTasks.length) return pool;
  const nonAnalTasks = pool.filter((task) => !isSoloAnalTask(task));
  if (!state.gameSettings?.anal) return nonAnalTasks;
  if (!soloAnalAllowed()) return nonAnalTasks.length ? nonAnalTasks : pool;
  return pool;
}

