function antiRepeatLimit(length, coverage = 0.92) {
  if (length <= 1) return 1;
  return Math.min(length - 1, Math.max(1, Math.floor(length * coverage)));
}

function stableTextKey(text, index) {
  return `${index}:${String(text).slice(0, 64)}`;
}

function taskGlobalSignature(item, fallbackKey = "") {
  const id = item?.id ? String(item.id) : "";
  const title = item?.title ? String(item.title) : "";
  const key = title || id || String(fallbackKey || "");
  return key.trim().toLowerCase().replace(/\s+/g, " ").slice(0, 120);
}

function pickTextFromList(list, historyKey) {
  const items = list.map((text, index) => ({
    id: stableTextKey(text, index),
    text
  }));
  const picked = pickWithoutQuickRepeat(
    items,
    historyKey,
    (item) => item.id,
    () => 1,
    antiRepeatLimit(items.length)
  );
  return picked?.text || list[0] || "";
}

function pickWithoutQuickRepeat(items, historyKey, keyForItem, weightForItem, maxHistory) {
  if (!items.length) return null;
  const historyLimit = Number.isFinite(maxHistory)
    ? Math.max(1, Math.min(items.length, maxHistory))
    : antiRepeatLimit(items.length);
  const existingKeys = new Set(items.map(keyForItem));
  const cleanedHistory = Array.isArray(state[historyKey])
    ? state[historyKey].filter((key) => existingKeys.has(key))
    : [];
  const recent = new Set(cleanedHistory.slice(-historyLimit));
  const available = items.filter((item) => !recent.has(keyForItem(item)));
  const scopedPool = available.length ? available : items;
  const globalHistory = Array.isArray(state.taskSignatureHistory) ? state.taskSignatureHistory : [];
  const globalRecent = new Set(globalHistory.slice(-160));
  const globalAvailable = scopedPool.filter((item) => !globalRecent.has(taskGlobalSignature(item, keyForItem(item))));
  const minGlobalPool = scopedPool.length <= 3 ? 1 : Math.min(4, Math.ceil(scopedPool.length * 0.18));
  const pool = globalAvailable.length >= minGlobalPool ? globalAvailable : scopedPool;
  const weighted = pool.flatMap((item) => Array.from({ length: Math.max(1, weightForItem(item)) }, () => item));
  const picked = weighted[Math.floor(Math.random() * weighted.length)] || pool[0];
  const pickedKey = keyForItem(picked);
  const nextHistory = [...cleanedHistory, pickedKey].slice(-historyLimit);
  state[historyKey] = nextHistory;
  state.taskSignatureHistory = [...globalHistory, taskGlobalSignature(picked, pickedKey)].slice(-220);
  saveState();
  return picked;
}

function buildPositionTask() {
  const sourcePositions = matchedPositionPrompts.length ? matchedPositionPrompts : positionPrompts;
  const contextSource = sourcePositions.filter((item) =>
    taskContextAllowed(item.tags || [], `${item.title || ""} ${item.setup || ""} ${item.focus || ""}`)
  );
  const contextPool = contextSource.length >= Math.min(4, sourcePositions.length) ? contextSource : sourcePositions;
  const directPool = uniquePositionsByVisualKey(contextPool.filter((item) =>
    isDirectPositionUrl(item.curatedUrl) &&
    !isBlockedPositionSource(item.curatedUrl)
  ));
  const curatedPool = uniquePositionsByVisualKey(contextPool.filter((item) =>
    item.curatedUrl &&
    item.curatedQuality !== "aehnlich" &&
    !isBlockedPositionSource(item.curatedUrl)
  ));
  const pool = directPool.length
    ? directPool
    : curatedPool.length
      ? curatedPool
      : contextPool;
  const familyHistory = Array.isArray(state.positionFamilyHistory) ? state.positionFamilyHistory : [];
  const familyKnown = new Set(pool.map(positionFamilyKey));
  const cleanFamilyHistory = familyHistory.filter((key) => familyKnown.has(key));
  const recentFamilies = new Set(cleanFamilyHistory.slice(-Math.min(8, Math.max(3, familyKnown.size - 1))));
  const familyFiltered = pool.filter((item) => !recentFamilies.has(positionFamilyKey(item)));
  const finalPool = familyFiltered.length >= Math.min(5, pool.length) ? familyFiltered : pool;
  const position = pickWithoutQuickRepeat(
    finalPool,
    "positionHistory",
    positionVisualKey,
    positionWeight,
    antiRepeatLimit(finalPool.length, 0.98)
  );
  state.positionFamilyHistory = [...cleanFamilyHistory, positionFamilyKey(position)].slice(-100);
  saveState();
  return {
    title: position.title,
    text: "",
    position,
    tags: position.tags || []
  };
}

