  const contextFootFollowUps = roleSource.filter((item) => taskContextAllowed(item.tags || [], `${item.title || ""} ${item.text || ""}`));
  const sourceFootFollowUps = contextFootFollowUps.length >= Math.min(8, roleSource.length) ? contextFootFollowUps : roleSource;
  const facetPool = sourceFootFollowUps.filter((item) => footTaskFacet(item) === facetId);
  const basePool = facetPool.length >= 4 ? facetPool : sourceFootFollowUps;
