function footContinuationContext(task = currentTaskDraft) {
  const title = task?.title || "";
  const text = task?.text || "";
  const tags = new Set(inferTaskTags(title, text, task?.tags || []));
  const lower = `${title} ${text}`.toLowerCase();
  const locations = footLocationTags.filter((tag) => tags.has(tag) || lower.includes(tag));
  const remote = footRemoteTags.some((tag) => tags.has(tag)) || /foto|video|nachricht|schick|sprachnotiz|online|link|tagsueber/.test(lower);
  const sexish = tags.has("sex") ||
    tags.has("position") ||
    tags.has("footjob") ||
    /sex|stellung|penis|schwanz|orgasmus|schritt|footjob|kommen/.test(lower);
  const active = !remote && (
    tags.has("foot-scene") ||
    sexish ||
    tags.has("oral") ||
    tags.has("massage") ||
    tags.has("care") ||
    footActivePattern.test(lower)
  );

  return {
    tags,
    lower,
    locations,
    remote,
    active,
    sexish,
    key: active ? `active-${locations.join("-") || "any"}` : remote ? "remote" : "soft"
  };
}

function footContinuationTags(item) {
  return new Set(inferTaskTags(item.title, item.text, item.tags || []));
}

function hasAnyTag(tags, values) {
  return values.some((tag) => tags.has(tag));
}

function meaningfulFootOverlap(tags, context) {
  return [...tags].some((tag) => context.tags.has(tag) && !footNeutralTags.includes(tag));
}

function footContinuationAllowed(item, context) {
  const tags = footContinuationTags(item);
  const text = `${item.title} ${item.text}`;
  const candidateLocations = footLocationTags.filter((tag) => tags.has(tag) || text.toLowerCase().includes(tag));

  if (context.active) {
    if (hasAnyTag(tags, footRemoteTags) || footPlanningPattern.test(text)) return false;
    if (candidateLocations.length && !candidateLocations.some((tag) => context.locations.includes(tag))) return false;
    if (tags.has("nylons") && !context.tags.has("nylons")) return false;
    if (tags.has("shoes") && !context.tags.has("shoes") && !context.tags.has("heels") && !context.tags.has("boots")) return false;
    if (!context.sexish && (tags.has("sex") || tags.has("position") || tags.has("footjob") || tags.has("edging"))) return false;
    if (tags.has("style")) return false;
    return true;
  }

  if (context.remote) {
    if (tags.has("sex") || tags.has("position") || tags.has("footjob")) return false;
    if (candidateLocations.length) return false;
    return hasAnyTag(tags, ["message", "media", "photo", "video", "prep", "show", "solo", "style", "shoes", "nylons", "talk"]);
  }

  return true;
}

function footContinuationScore(item, context) {
  const tags = footContinuationTags(item);
  let score = footTaskWeight(item);
  if (meaningfulFootOverlap(tags, context)) score += 12;
  context.locations.forEach((location) => {
    if (tags.has(location)) score += 10;
  });
  if (context.active && !hasAnyTag(tags, footRemoteTags)) score += 8;
  if (context.remote && hasAnyTag(tags, ["message", "media", "photo", "video", "prep"])) score += 8;
  return score;
}

function buildFootContinuation() {
  const scripted = buildScriptedFootContinuation();
  if (scripted) return scripted;

  const context = footContinuationContext();
  const allowed = footContinuationPool.filter((item) => footContinuationAllowed(item, context));
  const close = allowed.filter((item) => meaningfulFootOverlap(footContinuationTags(item), context));
  const pool = close.length >= 3 ? close : allowed.length ? allowed : footContinuationPool;
  const task = pickWithoutQuickRepeat(
    pool,
    `footContinuationHistory-${context.key}`,
    (item) => item.id,
    (item) => footContinuationScore(item, context),
    antiRepeatLimit(pool.length, 0.96)
  );
  return {
    title: cleanFootContinuationTitle(task.title),
    text: task.text,
    tags: task.tags || []
  };
}

