function randomTasksForMode(modeId, settings) {
  const allowScarce = (modeId === "experiment" || modeId === "surprise") && shouldOfferScarceTheme();
  const allowed = guidedRandomTasks.filter((task) => {
    if (!settings.anal && task.tags.includes("anal")) return false;
    if (!taskSoftAllowedForActivePlayer(task)) return false;
    if (isScarceSwingerDominance(task) && !allowScarce) return false;
    const rawText = typeof task.text === "function" ? "" : task.text || "";
    if (!taskContextAllowed(task.tags || [], `${task.title || ""} ${rawText}`)) return false;
    return true;
  });
  const balancedAllowed = balanceSoloAnalPool(allowed);
  if (modeId === "surprise") return balancedAllowed.length ? balancedAllowed : allowed;
  if (modeId === "daybuild") return balancedAllowed.length ? balancedAllowed : allowed;
  const filtered = balanceSoloAnalPool(balancedAllowed.filter((task) => (task.modes || []).includes(modeId)));
  return filtered.length ? filtered : balancedAllowed.length ? balancedAllowed : allowed;
}

function buildDayBuildTask() {
  const plan = pickWithoutQuickRepeat(
    dayBuildPlans,
    "dayBuildHistory",
    (item) => item.id,
    () => 1,
    antiRepeatLimit(dayBuildPlans.length, 0.98)
  );

  return {
    title: plan.title,
    text: "Alltag als Vorspiel nutzen. Koerperlich wird es nur, wenn es wirklich passt.",
    steps: plan.steps,
    randomMode: "daybuild",
    tags: plan.tags || []
  };
}

function truthDareWeight(card) {
  const settings = state.gameSettings || defaultGameSettings;
  const tags = card.tags || [];
  const profile = profileWords();
  let weight = 2 + tagLearningScore(tags);
  const rawText = typeof card.text === "function" ? "" : card.text || "";
  weight += taskContextScore(tags, `${card.title || ""} ${rawText}`);

  const settingWeights = {
    truth: settings.directness + settings.novelty,
    "hard-truth": settings.directness + settings.novelty + settings.languageHardness,
    dare: settings.lead + settings.directness + 6,
    "hard-dare": settings.lead + settings.directness + settings.languageHardness + 12,
    overcome: settings.lead + settings.directness + 8,
    sex: settings.directness + settings.lead + 8,
    physical: settings.directness + settings.lead + 7,
    talk: settings.directness,
    language: settings.languageHardness,
    fantasy: settings.novelty + settings.directness,
    feet: settings.feet,
    nylons: settings.nylons,
    oral: settings.oral,
    blowjob: settings.blowjobFeet + settings.oral,
    "foot-blowjob": settings.blowjobFeet + settings.feet + settings.oral,
    media: settings.media,
    photo: settings.media,
    video: settings.media + settings.directness,
    camera: settings.media + settings.directness,
    cam: settings.media + settings.experiment,
    online: settings.media + settings.experiment,
    live: settings.media + settings.experiment,
    privacy: 1,
    voyeur: settings.media + settings.experiment,
    porn: settings.media,
    masturbation: settings.solo + settings.directness,
    third: settings.experiment + settings.directness,
    jealousy: settings.novelty + settings.directness + settings.taboo,
    comparison: settings.directness + settings.languageHardness + settings.taboo,
    desire: settings.directness + settings.lead,
    memory: settings.novelty + settings.directness,
    "sex-expert": settings.sexExpert,
    clitoris: settings.sexExpert + settings.oral,
    gspot: settings.sexExpert + settings.novelty,
    dirty: settings.directness,
    experiment: settings.experiment + settings.novelty,
    novelty: settings.novelty,
    trust: settings.lead,
    control: settings.lead + settings.dominance,
    dominance: settings.lead + settings.dominance,
    submission: settings.lead + settings.dominance,
    toy: settings.toys + settings.novelty,
    vibrator: settings.toys + settings.sexExpert,
    place: settings.places + settings.novelty,
    hotel: settings.places + settings.novelty,
    car: settings.places + settings.novelty,
    prep: settings.novelty,
    kitchen: settings.kitchen + settings.places,
    message: settings.media + settings.directness
  };

  tags.forEach((tag) => {
    weight += Number(settingWeights[tag] || 0);
    if (profile.includes(tag)) weight += 2;
  });
  if (profile.includes("fuss") && tags.includes("feet")) weight += 4;
  if (profile.includes("nylon") && tags.includes("nylons")) weight += 3;
  if (profile.includes("oral") && tags.includes("oral")) weight += 3;
  if (profile.includes("porno") && tags.includes("porn")) weight += 2;
  if ((profile.includes("dreier") || profile.includes("3er")) && tags.includes("third")) weight += 4;
  if ((profile.includes("selbstbefried") || profile.includes("masturb") || profile.includes("wichs")) && tags.includes("masturbation")) weight += 3;
  if ((profile.includes("eifersucht") || profile.includes("eifersuechtig")) && tags.includes("jealousy")) weight += 3;
  if ((profile.includes("cam") || profile.includes("kamera")) && (tags.includes("cam") || tags.includes("camera"))) weight += 4;
  if (profile.includes("onlyfans") && tags.includes("platform")) weight += 4;
  if ((profile.includes("live") || profile.includes("voyeur")) && (tags.includes("live") || tags.includes("voyeur"))) weight += 3;
  if (profile.includes("online") && tags.includes("online")) weight += 2;
  if (Array.isArray(card.forPlayers) && card.forPlayers.includes(activePlayContext().actorIndex)) weight += 8;
  if (card.type === "dare") {
    if (tags.includes("message") && !tags.includes("physical") && !tags.includes("sex") && !tags.includes("oral")) weight -= 6;
    if (tags.includes("prep") && !tags.includes("physical")) weight -= 4;
    if (tags.includes("dayplay") && !tags.includes("hard-dare")) weight -= 5;
    if (tags.includes("hard-dare") || tags.includes("overcome")) weight += 12;
    if (tags.includes("sex") || tags.includes("oral") || tags.includes("physical")) weight += 8;
  }
  return Math.max(1, Math.round(weight));
}

function normalizeTruthGameMode(modeId = "") {
  return truthGameModes.some((mode) => mode.id === modeId) ? modeId : "";
}

function truthGameModeLabel(modeId = "") {
  return truthGameModes.find((mode) => mode.id === normalizeTruthGameMode(modeId))?.label || "Wie bisher";
}

function getAvailableShortGameModes(context = truthDareActorContext()) {
  return getAvailableGameOptions(context).modes;
}

function truthCardMode(card = {}) {
  return normalizeShortGameCard(card).mode || "intro";
}

function truthCardIntensity(card = {}) {
  return normalizeShortGameCard(card).intensity || 1;
}

function truthCardMatchesMode(card, modeId = "") {
  const safeMode = normalizeTruthGameMode(modeId);
  if (!safeMode) return true;
  const mode = getShortGameModeConfig(safeMode);
  if (!mode) return true;
  const normalized = normalizeShortGameCard(card);
  const tags = new Set(normalized.tags || []);
  if (Number(normalized.intensity) < mode.minIntensity || Number(normalized.intensity) > mode.maxIntensity) return false;
  if (mode.blockedTags.some((tag) => tags.has(tag))) return false;
  if (Array.isArray(mode.allowedGameTypes) && mode.allowedGameTypes.length && !mode.allowedGameTypes.includes(normalized.gameType)) return false;
  if (Array.isArray(normalized.matchTypes) && normalized.matchTypes.length && normalized.matchTypes.includes("blocked")) return false;
  if (mode.requiresBothConsent && !mode.allowedGameTypes.includes(normalized.gameType)) return false;
  if (safeMode === "intro") return normalized.mode === "intro" && normalized.intensity <= 1;
  if (safeMode === "playful") return normalized.mode === "intro" || normalized.mode === "playful";
  if (safeMode === "direct") return normalized.mode === "playful" || normalized.mode === "direct";
  if (safeMode === "intense") return normalized.mode === "direct" || normalized.mode === "intense" || normalized.intensity >= 4;
  return true;
}

function scoreShortGameCard(card = {}, context = {}) {
  const normalized = normalizeShortGameCard(card);
  const modeId = normalizeTruthGameMode(context.modeId || normalized.mode || "");
  const mode = getShortGameModeConfig(modeId);
  const drawType = String(context.choice || "").trim();
  const topic = normalizeCardTopic(context.topic || normalized.topic || "");
  let score = truthDareWeight(normalized);

  if (modeId && normalized.mode === modeId) score += 6;
  if (mode && Number(normalized.intensity) >= mode.minIntensity && Number(normalized.intensity) <= mode.maxIntensity) score += 4;
  if (Array.isArray(mode.preferredTags)) {
    mode.preferredTags.forEach((tag) => {
      if ((normalized.tags || []).includes(tag)) score += 2;
    });
  }
  if (Array.isArray(mode.blockedTags)) {
    mode.blockedTags.forEach((tag) => {
      if ((normalized.tags || []).includes(tag)) score -= 5;
    });
  }
  if (drawType === "truth" && normalized.gameType === "truth") score += 8;
  if (drawType === "dare" && normalized.gameType === "dare") score += 8;
  if (drawType === "surprise" && ["truth", "dare"].includes(normalized.gameType)) score += 2;
  if (drawType === "choice" && normalized.gameType === "choice") score += 10;
  if (drawType === "quick_task" && normalized.gameType === "quick_task") score += 10;
  if (drawType === "mini_ritual" && normalized.gameType === "mini_ritual") score += 10;
  if (drawType === "couple_question" && normalized.gameType === "couple_question") score += 10;
  if (topic && inferCardTopic(normalized) === topic) score += 4;
  if (Array.isArray(normalized.matchTypes) && normalized.matchTypes.length && context.matchType && normalized.matchTypes.includes(context.matchType)) score += 4;
  if (normalized.drawerRole && normalized.drawerRole !== "either" && context.drawerRole && normalized.drawerRole === context.drawerRole) score += 2;
  if (normalized.targetRole && normalized.targetRole !== "either" && context.partnerRole && normalized.targetRole === context.partnerRole) score += 2;
  if (Array.isArray(context.preferredTags) && context.preferredTags.some((tag) => (normalized.tags || []).includes(tag))) score += 2;
  if (Array.isArray(context.blockedTags) && context.blockedTags.some((tag) => (normalized.tags || []).includes(tag))) score -= 20;
  if (context.maxAllowedIntensity && Number(normalized.intensity) > Number(context.maxAllowedIntensity)) score -= 40;
  return score;
}

function buildNeutralTruthDareCard(choice = "", modeId = "") {
  const safeChoice = choice === "dare" ? "dare" : choice === "surprise" ? "surprise" : "truth";
  const modeLabel = truthGameModeLabel(modeId);
  return {
    id: `truth-neutral-${safeChoice}-${modeId || "all"}`,
    type: safeChoice,
    neutral: true,
    title: "Heute passt eher ein ruhigerer Einstieg",
    text: modeId
      ? `Fuer ${modeLabel} gibt es gerade keinen sauberen Treffer. Wechselt den Modus oder bleibt bei Wie bisher.`
      : "Es gibt gerade keinen passenden Treffer. Wechselt den Modus oder versucht es spaeter noch einmal.",
    steps: [],
    tags: ["truth", "neutral", "talk"],
    mode: modeId || "",
    intensity: 1
  };
}

function activePlayContext() {
  const actorIndex = Number(state.activeIndex) === 1 ? 1 : 0;
  const partnerIndex = actorIndex === 0 ? 1 : 0;
  return {
    actorIndex,
    partnerIndex,
    actor: state.players[actorIndex] || (actorIndex === 0 ? "Christian" : "Jenny"),
    partner: state.players[partnerIndex] || (partnerIndex === 0 ? "Christian" : "Jenny")
  };
}

function truthDareActorContext() {
  return activePlayContext();
}

function taskAllowedForActivePlayer(task = {}) {
  if (!Array.isArray(task.forPlayers) || !task.forPlayers.length) return true;
  return task.forPlayers.includes(activePlayContext().actorIndex);
}

function taskSoftAllowedForActivePlayer(task = {}) {
  if (!taskAllowedForActivePlayer(task)) return false;
  if (Array.isArray(task.forPlayers) && task.forPlayers.length) return true;

  const { actorIndex } = activePlayContext();
  const titleText = typeof task.title === "function" ? "" : task.title || "";
  const bodyText = typeof task.text === "function" ? "" : task.text || "";
  const text = `${titleText} ${bodyText}`.toLowerCase();
  const christianAction = /\bchristian\s+(formuliert|schreibt|fragt|nennt|bestimmt|sucht|wichst|masturbiert|macht es sich)\b/;
  const jennyAction = /\bjenny\s+(formuliert|schreibt|fragt|schickt|fordert|testet|masturbiert|macht es sich|waehlt)\b/;

  if (actorIndex === 1 && christianAction.test(text)) return false;
  if (actorIndex === 0 && jennyAction.test(text)) return false;
  return true;
}

function truthDareCardAllowedForActivePlayer(card) {
  return taskSoftAllowedForActivePlayer(card);
}

function resolveTaskValue(value, context = activePlayContext()) {
  return typeof value === "function" ? value(context) : value;
}

function resolveTruthDareValue(value, context) {
  return resolveTaskValue(value, context);
}

function resolveTaskForActivePlayer(task = {}) {
  const context = activePlayContext();
  return {
    ...task,
    title: resolveTaskValue(task.title, context),
    text: resolveTaskValue(task.text, context),
    steps: Array.isArray(resolveTaskValue(task.steps, context))
      ? resolveTaskValue(task.steps, context).map((step) => ({
          ...step,
          time: resolveTaskValue(step.time, context),
          title: resolveTaskValue(step.title, context),
          text: resolveTaskValue(step.text, context)
        }))
      : task.steps
  };
}

function resolveTruthDareSteps(card, context) {
  const steps = resolveTruthDareValue(card.steps, context);
  return Array.isArray(steps)
    ? steps.map((step) => ({
        time: resolveTruthDareValue(step.time, context),
        title: resolveTruthDareValue(step.title, context),
        text: resolveTruthDareValue(step.text, context)
      }))
    : [];
}

function buildTruthOrDareTask(choice = "", modeId = "") {
  const settings = state.gameSettings || defaultGameSettings;
  const safeChoice = choice === "truth" || choice === "dare" || choice === "surprise" ? choice : "";
  const safeMode = normalizeTruthGameMode(modeId || state.truthGameMode || "");
  const context = truthDareActorContext();
  const sourcePool = getShortGameSelectionCards({ choice: safeChoice || "surprise", modeId: safeMode }, context).filter((card) => {
    if (!settings.anal && (card.tags || []).includes("anal")) return false;
    if (safeMode === "intense" && !context.allowedModes?.intense) return false;
    return true;
  });
  if (!sourcePool.length) return buildNeutralTruthDareCard(safeChoice, safeMode);
  const card = pickWithoutQuickRepeat(
    sourcePool,
    safeChoice ? `truthDareHistory-${safeChoice}${safeMode ? `-${safeMode}` : ""}` : safeMode ? `truthDareHistory-${safeMode}` : "truthDareHistory",
    (item) => item.id,
    (item) => scoreShortGameCard(item, { choice: safeChoice || "surprise", modeId: safeMode, ...context }),
    antiRepeatLimit(sourcePool.length, 0.94)
  );
  const resolvedSteps = resolveTruthDareSteps(card, context);
  const steps = resolvedSteps.length ? resolvedSteps : buildTruthDareSteps(card);
  return {
    id: card.id,
    title: resolveTruthDareValue(card.title, context),
    text: resolveTruthDareValue(card.text, context),
    steps,
    gameType: card.gameType || card.type,
    randomMode: card.type,
    type: card.type,
    completionType: card.completionType,
    requiredInputs: card.requiredInputs,
    optionalInputs: card.optionalInputs,
    requiresBothConsent: Boolean(card.requiresBothConsent),
    drawerRole: card.drawerRole || "either",
    targetRole: card.targetRole || "either",
    matchTypes: Array.isArray(card.matchTypes) ? [...card.matchTypes] : [],
    focusPerson: card.focusPerson || "drawer",
    mode: safeMode || truthCardMode(card) || "",
    intensity: truthCardIntensity(card),
    neutral: Boolean(card.neutral),
    answerRule: card.answerRule || "",
    safetyRule: card.safetyRule || "",
    overcomesWhat: Array.isArray(card.overcomesWhat) ? [...card.overcomesWhat] : [],
    feedbackTags: Array.isArray(card.feedbackTags) ? [...card.feedbackTags] : [...(card.tags || [])],
    tags: [...(card.tags || []), card.type, "dayplay"]
  };
}

function buildTruthDareSteps(card) {
  return [];
}

function truthDareLabel(choice) {
  return choice === "truth" ? "Wahrheit" : "Pflicht";
}

function forcedTruthDareChoice() {
  const streak = state.truthDareStreak || { type: "", count: 0 };
  if (streak.type === "truth" && streak.count >= 4) return "dare";
  if (streak.type === "dare" && streak.count >= 4) return "truth";
  return "";
}

function recordTruthDareChoice(choice) {
  if (choice !== "truth" && choice !== "dare") return;
  const streak = state.truthDareStreak || { type: "", count: 0 };
  state.truthDareStreak = streak.type === choice
    ? { type: choice, count: Math.min(4, Number(streak.count || 0) + 1) }
    : { type: choice, count: 1 };
}

function truthDareDueScope(task = currentTaskDraft) {
  const tags = task?.tags || [];
  const text = `${task?.title || ""} ${task?.text || ""} ${(task?.steps || []).map((step) => `${step.time} ${step.title} ${step.text}`).join(" ")}`.toLowerCase();
  if (tags.includes("experiment") || tags.includes("prep") || /diese woche|woche|wochenende/.test(text)) return "week";
  return "day";
}

function registerPendingTruthDareDuty(choice) {
  if (choice !== "dare" || elements.shareAcceptedTask.checked || !currentTaskDraft) return;
  const now = new Date();
  state.pendingTruthDareDuty = {
    id: `${Date.now()}-${Math.random().toString(36).slice(2)}`,
    title: currentTaskDraft.title || "Pflicht",
    text: currentTaskDraft.text || "",
    steps: Array.isArray(currentTaskDraft.steps) ? currentTaskDraft.steps : [],
    tags: currentTaskDraft.tags || [],
    starter: state.activeIndex,
    createdAt: now.toISOString(),
    dayKey: todayKey(),
    weekKey: weekKey(now),
    dueScope: truthDareDueScope(currentTaskDraft)
  };
}

function completePendingTruthDareDuty() {
  const pending = state.pendingTruthDareDuty;
  if (!pending || !currentTaskDraft) return;
  if (pending.title === currentTaskDraft.title && pending.text === currentTaskDraft.text) {
    state.pendingTruthDareDuty = null;
  }
}

function isTruthDareDutyOverdue(duty) {
  if (!duty) return false;
  if (duty.dueScope === "week") return duty.weekKey !== weekKey();
  return duty.dayKey !== todayKey();
}

function revealOverdueTruthDareDuty() {
  const duty = state.pendingTruthDareDuty;
  if (!isTruthDareDutyOverdue(duty)) return;
  const starter = Number.isInteger(duty.starter) ? duty.starter : 0;
  const now = new Date().toISOString();
  state.activeTask = {
    id: `missed-${duty.id || Date.now()}`,
    categoryId: "random",
    categoryTitle: "Pflicht oder Wahrheit",
    title: `Nicht eingehalten: ${duty.title}`,
    text: duty.text,
    steps: Array.isArray(duty.steps) ? duty.steps : [],
    starter,
    visible: true,
    status: "active",
    startedAt: duty.createdAt || now,
    comments: [
      {
        type: "system",
        player: starter,
        text: `${state.players[starter]} hat eine private Pflicht nicht eingehalten. We2 legt sie jetzt offen.`,
        at: now
      }
    ]
  };
  state.pendingTruthDareDuty = null;
  saveState();
  renderTaskThread();
}

function buildGuidedRandomTask(modeId = "surprise") {
  const settings = state.gameSettings || defaultGameSettings;
  const safeMode = randomModes.some((mode) => mode.id === modeId) ? modeId : "surprise";
  if (safeMode === "daybuild") return buildDayBuildTask();

  const candidates = randomTasksForMode(safeMode, settings);
  const task = pickWithoutQuickRepeat(
    candidates,
    safeMode === "surprise" ? "guidedTaskHistory" : `guidedTaskHistory-${safeMode}`,
    (item) => item.title,
    guidedTaskWeight,
    antiRepeatLimit(candidates.length, 0.94)
  );
  if (safeMode === "experiment" || safeMode === "surprise") {
    recordScarceThemePick(Boolean(task && isScarceSwingerDominance(task)));
  }
  recordSoloAnalPick(task);
  const resolvedTask = resolveTaskForActivePlayer(task);
  return {
    title: resolvedTask.title,
    text: resolvedTask.text,
    randomMode: safeMode,
    tags: resolvedTask.tags || []
  };
}

function getAvailableCards() {
  const category = elements.categorySelect.value;
  const tag = elements.tagSelect.value;
  const modeId = getSelectedCardMode();
  const topic = getSelectedCardTopic();
  const context = buildCardDrawContext({ modeId, topic, drawerIndex: state.activeIndex });
  const pool = [...cards, ...state.customCards].map((card) => normalizeCardCompletion(card));
  const filtered = pool.filter((card) => {
    const categoryMatches = category === "all" || card.category === category;
    const tagMatches = tag === "all" || (card.tags || []).includes(tag);
    const topicMatches = !topic || inferCardTopic(card) === topic || (card.tags || []).includes(topic);
    return categoryMatches && tagMatches && topicMatches && taskContextAllowed(card.tags || [], `${card.title || ""} ${card.text || ""}`);
  });
  const modeFiltered = getCardsForMode(filtered, modeId, context);
  return modeFiltered.filter((card) => isCardPlayable(card, context));
}

function weightedPick(items) {
  const weighted = items.flatMap((card) => Array.from({ length: cardWeight(card) }, () => card));
  return weighted[Math.floor(Math.random() * weighted.length)];
}

function todayKey() {
  return new Date().toISOString().slice(0, 10);
}

function dateInputValue(date = new Date()) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function sexDateFromInput(value) {
  const match = String(value || "").match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return new Date();
  const [, year, month, day] = match;
  return new Date(Number(year), Number(month) - 1, Number(day), 12, 0, 0, 0);
}

function weekKey(date = new Date()) {
  return startOfWeek(date).toISOString().slice(0, 10);
}

function monthKey() {
  return new Date().toISOString().slice(0, 7);
}

function yesterdayKey() {
  const date = new Date();
  date.setDate(date.getDate() - 1);
  return date.toISOString().slice(0, 10);
}

function todayLog() {
  const key = todayKey();
  if (!state.dailyLog[key]) state.dailyLog[key] = {};
  return state.dailyLog[key];
}

function currentWeekLog() {
  const key = weekKey();
  if (!state.weeklyLog[key]) state.weeklyLog[key] = {};
  return state.weeklyLog[key];
}

function currentWeekScore() {
  const key = weekKey();
  if (!state.weeklyScores || typeof state.weeklyScores !== "object") state.weeklyScores = {};
  const entry = state.weeklyScores[key];
  const scores = Array.isArray(entry?.scores) ? entry.scores : Array.isArray(entry) ? entry : [0, 0];
  state.weeklyScores[key] = { scores: [Number(scores[0]) || 0, Number(scores[1]) || 0] };
  return state.weeklyScores[key];
}

function isPlayedThisWeek(categoryId) {
  return Boolean(currentWeekLog()[categoryId]);
}

function markPlayedThisWeek(categoryId) {
  const key = weekKey();
  if (!state.weeklyLog[key]) state.weeklyLog[key] = {};
  state.weeklyLog[key][categoryId] = true;

  const allPlayed = dailyCategories.every((category) => state.weeklyLog[key][category.id]);
  if (allPlayed && !state.weeklyRewards[key]) {
    const bonus = normalizedWeeklyRewardPoints();
    const winners = weeklyWinnerIndexes();
    state.weeklyRewards[key] = {
      awarded: true,
      points: bonus,
      winners,
      at: new Date().toISOString()
    };
    winners.forEach((winnerIndex) => addPoints(winnerIndex, bonus));
    elements.taskStatus.hidden = false;
    elements.taskStatusText.textContent = weeklyRewardStatusText(winners, bonus);
  }
}

function weeklyWinnerIndexes() {
  const scores = currentWeekScore().scores;
  if (scores[0] === scores[1]) return [0, 1];
  return [scores[0] > scores[1] ? 0 : 1];
}

function weeklyRewardStatusText(winners, points) {
  const names = winners.map((index) => state.players[index]).join(" und ");
  return `Woche gewonnen: ${names} bekommt ${points}.`;
}

function getTotalPoints() {
  return (state.playerScores[0] || 0) + (state.playerScores[1] || 0);
}

function startOfWeek(date) {
  const copy = new Date(date);
  const day = copy.getDay() || 7;
  copy.setHours(0, 0, 0, 0);
  copy.setDate(copy.getDate() - day + 1);
  return copy;
}

function updateSexTracker() {
  if (!elements.weekSexCount || !elements.monthSexCount || !elements.lifeSexCount) return;

  const now = new Date();
  const weekStart = startOfWeek(now);
  const lastWeekStart = new Date(weekStart);
  lastWeekStart.setDate(lastWeekStart.getDate() - 7);
  const currentMonth = monthKey();
  const log = state.records.sexLog || [];
  const weekCount = log.filter((entry) => new Date(entry.at) >= weekStart).length;
  const lastWeekCount = log.filter((entry) => {
    const date = new Date(entry.at);
    return date >= lastWeekStart && date < weekStart;
  }).length;
  const monthCount = log.filter((entry) => entry.at?.slice(0, 7) === currentMonth).length;
  const appCount = log.filter((entry) => entry.appInvolved).length;
  elements.weekSexCount.textContent = String(weekCount);
  if (elements.lastWeekSexCount) elements.lastWeekSexCount.textContent = String(lastWeekCount);
  elements.monthSexCount.textContent = String(monthCount);
  if (elements.appSexCount) elements.appSexCount.textContent = String(appCount);
  elements.lifeSexCount.textContent = String(log.length);
}

function recordSex(date = new Date(), appInvolved = false) {
  if (!Array.isArray(state.records.sexLog)) state.records.sexLog = [];
  state.records.sexLog.push({
    at: date.toISOString(),
    dateKey: dateInputValue(date),
    appInvolved: Boolean(appInvolved)
  });
  updateSexTracker();
}

function submitSexTrackerEntry(event) {
  event.preventDefault();
  const date = sexDateFromInput(elements.sexDateInput.value);
  const appInvolved = Boolean(elements.sexAppInvolved.checked);
  recordSex(date, appInvolved);
  saveState();
  updateSexTracker();
  const label = date.toLocaleDateString("de-DE", { day: "2-digit", month: "2-digit", year: "numeric" });
  elements.sexTrackerStatus.textContent = appInvolved
    ? `${label} eingetragen. We2 war beteiligt.`
    : `${label} eingetragen. Ohne direkte We2-Beteiligung.`;
  elements.sexDateInput.value = dateInputValue();
  elements.sexAppInvolved.checked = false;
}

function addPoints(playerIndex, playerPoints, options = {}) {
  const points = Number(playerPoints) || 0;
  state.playerScores[playerIndex] = (state.playerScores[playerIndex] || 0) + points;
  if (!options.skipWeekly) {
    const week = currentWeekScore();
    week.scores[playerIndex] = (week.scores[playerIndex] || 0) + points;
  }
  state.sharedPoints = getTotalPoints();
  state.xp = state.sharedPoints;
  updateRecords();
  updateRewardState();
  if (elements.pointsView && !elements.pointsView.hidden) renderWeekProgress();
  animatePointCounters();
}

function animatePointCounters() {
  window.setTimeout(() => {
    [
      elements.activePlayerPoints,
      elements.pointsPlayerOne,
      elements.pointsPlayerTwo,
      elements.pointsShared,
      elements.xpCount
    ].filter(Boolean).forEach((element) => {
      element.classList.remove("points-pop");
      void element.offsetWidth;
      element.classList.add("points-pop");
    });
  }, 0);
}

function updateRecords() {
  const currentMonth = monthKey();
  if (state.records.monthKey !== currentMonth) {
    state.records.monthKey = currentMonth;
    state.records.monthBest = 0;
  }
  const total = getTotalPoints();
  state.records.lifeBest = Math.max(state.records.lifeBest || 0, total);
  state.records.monthBest = Math.max(state.records.monthBest || 0, total);
}

function updateDailyStreak() {
  if (state.lastDailyCompleted === todayKey()) return;
  state.streak = state.lastDailyCompleted === yesterdayKey() ? state.streak + 1 : 1;
  state.lastDailyCompleted = todayKey();
}

function updateRewardState() {
  const nextRewardAt = (state.rewardsClaimed + 1) * 100;
  const ready = getTotalPoints() >= nextRewardAt;
  const reward = rewardForIndex(state.rewardsClaimed);
  if (elements.rewardText) {
    elements.rewardText.textContent = ready
      ? `Bereit: ${reward}`
      : `${reward} bei ${nextRewardAt}`;
  }
  if (elements.claimReward) elements.claimReward.disabled = !ready;
}

function renderDailyCategories() {
  revealOverdueTruthDareDuty();
  elements.dailyTaskList.innerHTML = "";

  dailyCategories.forEach((category) => {
    const item = document.createElement("button");
    const title = document.createElement("h3");
    const subtitle = document.createElement("small");
    const points = document.createElement("strong");
    const playedThisWeek = isPlayedThisWeek(category.id);
    const action = getExecutionAction(category);
    const pointValue = Number(action.playerPoints) || 0;

    item.className = "daily-task";
    item.classList.toggle("week-played", playedThisWeek);
    item.classList.toggle("week-missing", !playedThisWeek);
    item.type = "button";
    item.setAttribute("aria-label", `${category.title}, ${playedThisWeek ? "diese Woche gespielt" : "diese Woche offen"}`);
    title.textContent = category.title;
    subtitle.className = "daily-task-subtitle";
    subtitle.textContent = category.id === "random"
      ? `Modus: ${truthGameModeLabel(state.truthGameMode || "") || "Wie bisher"}`
      : "";
    subtitle.hidden = !subtitle.textContent;
    points.className = "daily-task-points";
    points.textContent = String(pointValue);
    item.addEventListener("click", () => openCategory(category.id));

    item.append(points, title, subtitle);
    elements.dailyTaskList.append(item);
  });

  updateLabels();
  if (!elements.pointsView.hidden) renderWeekProgress();
}

function getCategory(categoryId) {
  return dailyCategories.find((category) => category.id === categoryId);
}

