function tagLearningScore(tags = []) {
  const learned = state.learnedTags || {};
  return tags.reduce((sum, tag) => sum + Math.min(5, Number(learned[tag] || 0)), 0);
}

function learnFromTask(categoryId, strength = 1, task = currentTaskDraft) {
  const category = getCategory(categoryId);
  const tags = inferTaskTags(
    task?.title || category?.title || "",
    task?.text || category?.text || "",
    task?.tags || []
  );
  if (!tags.length) return;
  if (!state.learnedTags || typeof state.learnedTags !== "object") state.learnedTags = {};
  tags.forEach((tag) => {
    state.learnedTags[tag] = Math.min(20, Number(state.learnedTags[tag] || 0) + strength);
  });
}

function languageHardness() {
  return Number(state.gameSettings?.languageHardness || defaultGameSettings.languageHardness || 1);
}

function directLanguageLine(title = "", text = "", tags = []) {
  const level = languageHardness();
  if (level <= 1 || !text) return "";

  const inferred = inferTaskTags(title, text, tags);
  const has = (tag) => inferred.includes(tag);

  if (level === 2) {
    return "Benutze: Penis, Vagina.";
  }

  if (level === 3) {
    if (has("oral") || has("feet")) return "Benutze: lecken, lutschen, Penis, Vagina.";
    if (has("message")) return "Schreib direkt: Penis, Vagina, lecken, lutschen.";
    return "Sag es direkt: Penis, Vagina, lecken, lutschen.";
  }

  if (level === 4) {
    if (has("oral")) return "Sag: lecken, lutschen, Penis, Vagina.";
    if (has("feet")) return "Sag: Fußsohle, Zehen, lecken, lutschen.";
    return "Sag es hart: Penis, Vagina, lecken, lutschen, ficken.";
  }

  if (has("fisting")) return "Sag: fisten, Penis, Vagina. Nur mit klarem Ja.";
  if (has("spitting")) return "Sag: spucken, lecken, lutschen. Nur als Angebot.";
  return "Sag es hart: Penis, Vagina, lecken, lutschen, spucken.";
}

