function renderPositionDetails(position, container = elements.delegatedTask) {
  if (!position || !container) return;
  const card = document.createElement("section");
  const facts = document.createElement("div");

  card.className = "position-card";
  facts.className = "position-facts";

  if (position.sourceNumber) appendPositionFact(facts, "Nummer", `#${position.sourceNumber}`, true);
  appendPositionFact(facts, "Schwierigkeit", position.difficulty || "Mittel");
  appendPositionFact(facts, "Fuß-tauglich", positionFlagLabel(position.footFriendly), position.footFriendly);
  appendPositionFact(facts, "Oral-tauglich", positionFlagLabel(position.oralFriendly), position.oralFriendly);

  card.append(facts);
  const linkBox = document.createElement("div");
  linkBox.className = "position-link-box";
  [
    {
      url: position.curatedUrl || position.sourceUrl || "",
      label: position.curatedLabel || position.sourceLabel || "Bild ansehen",
      primary: true
    },
    {
      url: position.imageSearchUrl || positionImageSearchUrl(position),
      label: "Bildsuche",
      primary: false
    }
  ].forEach((item) => {
    if (!item.url) return;
    const link = document.createElement("a");
    link.href = item.url;
    link.target = "_blank";
    link.rel = "noopener noreferrer";
    link.textContent = item.label;
    link.addEventListener("click", (event) => {
      event.preventDefault();
      openExternalPositionLink(item.url, item.label);
    });
    if (item.primary) link.className = "primary-link";
    linkBox.append(link);
  });
  if (linkBox.children.length) card.append(linkBox);
  container.append(card);
}

function openExternalPositionLink(url, label = "Link") {
  if (!url) return;
  externalOpenGraceUntil = Date.now() + 45000;
  let opened = null;
  try {
    opened = window.open(url, "_blank", "noopener,noreferrer");
  } catch {
    opened = null;
  }
  if (opened) return;
  navigator.clipboard?.writeText(url).then(() => {
    if (elements.taskStatus && elements.taskStatusText) {
      elements.taskStatus.hidden = false;
      elements.taskStatusText.textContent = `${label} kopiert. In neuem Tab oeffnen und mit Zurueck wieder zu We2.`;
    }
  }).catch(() => {
    if (elements.taskStatus && elements.taskStatusText) {
      elements.taskStatus.hidden = false;
      elements.taskStatusText.textContent = `${label}: ${url}`;
    }
  });
}

function compactTaskText(text = "", tags = []) {
  const clean = repairMojibakeText(String(text || "")).replace(/\s+/g, " ").trim();
  if (!clean) return "";

  const hardTags = ["anal", "bondage", "blindfold", "spitting", "fisting", "impact"];
  const hasHardTag = tags.some((tag) => hardTags.includes(tag));
  const sentences = clean.split(/(?<=[.!?])\s+/).filter(Boolean);
  const isFootScene = tags.includes("foot-scene");
  const isFootMore = tags.includes("foot-more");
  const isFootFacet = tags.includes("foot-facet") || tags.some((tag) => String(tag).startsWith("facet-"));
  const isSexExpert = tags.includes("sex-expert") || tags.includes("anatomy") || tags.includes("gspot") || tags.includes("clitoris");
  const isSoloTask = tags.includes("solo");
  const sentenceCount = (isFootScene || isFootMore) ? 3 : isFootFacet ? 2 : (isSexExpert || isSoloTask) ? 2 : 1;
  const maxLength = isFootScene ? 280 : isFootMore ? 340 : isFootFacet ? 240 : isSexExpert ? 260 : isSoloTask ? 210 : 145;
  let compact = sentences.slice(0, sentenceCount).join(" ") || clean;

  if (/^(We2|Ueberraschung|Nachrichten|Koerperlich|Kopfkino|Vorbereiten)[:.]?$/.test(compact) && sentences[1]) {
    compact = `${compact} ${sentences[1]}`;
  }

  if (hasHardTag && sentences[1] && !/Angebot|Ja|Nein|Stopp|Signal|frei/i.test(compact)) {
    compact = `${compact} ${sentences[1]}`;
  }

  if (compact.length > maxLength) {
    compact = `${compact.slice(0, maxLength - 3).replace(/\s+\S*$/, "")}.`;
  }

  if (tags.includes("fisting") && !/Ja|Angebot/i.test(compact)) return `${compact} Nur mit klarem Ja.`;
  if (tags.includes("spitting") && !/Angebot|Ja/i.test(compact)) return `${compact} Nur als Angebot.`;
  if (tags.includes("anal") && !/Angebot|Ja|Nein/i.test(compact)) return `${compact} Nur als Angebot.`;
  if ((tags.includes("bondage") || tags.includes("blindfold")) && !/Stopp|Signal/i.test(compact)) return `${compact} Stoppzeichen bleibt.`;

  return compact;
}

