function completeMediaRequestText(text) {
  const cleanText = String(text || "").trim();
  if (!cleanText) return false;
  if (state.pendingMediaRequest?.awaitingPartnerWish && state.pendingMediaRequest.requester !== state.activeIndex) return false;

  const action = getCategory("send-me")?.actions.find((item) => item.id === "request") || { label: "Wuensch dir was", playerPoints: 25 };
  const requestedFrom = state.pendingMediaRequest?.invitedBy;
  const requester = state.activeIndex;
  const requesterName = state.players[requester] || "Dein Partner";
  const requestedFromName = state.players[requestedFrom] || "Partner";
  state.pendingMediaRequest = {
    text: cleanText,
    requester,
    requestedFrom,
    generated: false,
    awaitingPartnerWish: false,
    at: new Date().toISOString()
  };
  currentTaskDraft = {
    title: `Wunsch von ${requesterName}`,
    text: `${requesterName} wÃ¼nscht sich von ${requestedFromName}: ${cleanText}`,
    steps: [],
    tags: ["media", "message", "request"],
    drawnBy: `${requestedFromName} setzt um`,
    roleLine: `${requestedFromName} nimmt das gewÃ¼nschte Foto oder Video auf. ${requesterName} reagiert.`
  };
  elements.shareAcceptedTask.checked = true;

  elements.mediaRequestForm.hidden = true;
  elements.mediaRequestInput.value = "";
  showAcceptedTask("send-me", action);
  if (state.activeTask?.categoryId === "send-me" && Number.isInteger(requestedFrom)) {
    state.activeTask.starter = requestedFrom;
    state.activeTask.drawnBy = `${requestedFromName} setzt um`;
    state.activeTask.roleLine = currentTaskDraft.roleLine;
    state.activeTask.pointsForBoth = false;
  }
  learnFromTask("send-me", 1, currentTaskDraft);
  saveState();
  renderMediaRequest();
  renderDailyCategories();
  updateLabels();
  return true;
}

function submitMediaRequest(event) {
  event.preventDefault();
  completeMediaRequestText(elements.mediaRequestInput.value);
}

async function submitTaskMedia(event) {
  event.preventDefault();
  const file = elements.taskMediaInput.files[0];
  if (!file) return;
  if (!/^(image|video|audio)\//.test(file.type)) {
    elements.taskMediaStatus.textContent = "Nur Bilder, Videos und Audios koennen gesendet werden.";
    return;
  }

  const caption = elements.taskMediaCaption.value.trim();
  const categoryId = currentMediaCategoryId || "send-me";
  const category = getCategory(categoryId) || getCategory("send-me");
  const mediaKind = file.type.startsWith("audio/")
    ? "Sprachnachricht"
    : file.type.startsWith("video/")
      ? "Video"
      : "Bild";
  const log = todayLog();
  const doneKey = categoryId === "send-me"
    ? (caption ? "send-me:spark" : "send-me:sent")
    : `${categoryId}:media`;
  const wasVaultOpen = Boolean(vaultKey);
  let key = vaultKey;

  elements.sendTaskMedia.disabled = true;
  elements.taskMediaStatus.textContent = "Verschluessle und speichere...";

  try {
    if (!key) key = await getVerifiedVaultKey(elements.taskMediaPassword.value);
    const savedRecord = await saveEncryptedMediaFile(file, {
      savedFrom: "task",
      sourceCategory: categoryId,
      sourceTitle: currentTaskDraft?.title || category?.title || "Aufgabe",
      taskText: currentTaskDraft?.text || "",
      caption,
      sender: state.activeIndex,
      senderName: state.players[state.activeIndex],
      visibleToPartner: elements.shareAcceptedTask.checked
    }, key);

    state.pendingMedia = {
      name: file.name,
      type: file.type,
      caption,
      vaultId: savedRecord.id,
      protected: true,
      sourceCategory: categoryId,
      sender: state.activeIndex,
      at: new Date().toISOString()
    };

    const sentAction = category?.actions?.find((item) => item.id === "sent") || { playerPoints: 25 };
    const sparkAction = category?.actions?.find((item) => item.id === "spark") || { playerPoints: 25 };
    const points = categoryId === "send-me" ? (caption ? sparkAction.playerPoints : sentAction.playerPoints) : 6;
    const alreadyDone = Boolean(log[doneKey]);
    if (!alreadyDone) {
      log[doneKey] = {
        player: state.activeIndex,
        at: new Date().toISOString(),
        visibleToPartner: elements.shareAcceptedTask.checked
      };
      addPoints(state.activeIndex, points);
      learnFromTask(categoryId, caption ? 2 : 1, { title: mediaKind, text: caption, tags: ["media", file.type.split("/")[0], file.type.startsWith("audio/") ? "voice" : "photo"] });
      markPlayedThisWeek(categoryId);
      updateDailyStreak();
    }

    const mediaLabel = categoryId === "send-me" ? (caption ? sparkAction.label : sentAction.label) : `${mediaKind} verschluesselt gesendet`;
    showAcceptedTask(categoryId, { label: mediaLabel, playerPoints: alreadyDone ? 0 : points });
    if (state.activeTask?.categoryId === categoryId) {
      state.activeTask.mediaSent = true;
      state.activeTask.pointsAwarded = true;
      state.activeTask.pointsForBoth = false;
    }
    elements.taskMediaInput.value = "";
    elements.taskMediaCaption.value = "";
    elements.taskMediaPassword.value = "";
    elements.taskMediaStatus.textContent = "Gespeichert. Zum Ansehen Privat oeffnen und Passwort eingeben.";
    if (wasVaultOpen) await renderMedia();
    saveState();
    renderSentMedia();
    renderDailyCategories();
  } catch (error) {
    elements.taskMediaStatus.textContent = error.message || "Medium konnte nicht gespeichert werden.";
  } finally {
    elements.sendTaskMedia.disabled = false;
  }
}

function renderMediaRequest() {
  if (!state.pendingMediaRequest) {
    elements.mediaRequestPreview.hidden = true;
    elements.mediaRequestForm.hidden = true;
    return;
  }

  elements.mediaRequestPreview.hidden = false;
  const awaiting = Boolean(state.pendingMediaRequest.awaitingPartnerWish);
  elements.mediaRequestMeta.textContent = state.pendingMediaRequest.generated
    ? "App gibt vor"
    : awaiting
      ? `Bitte an ${state.players[state.pendingMediaRequest.requester] || "Partner"}`
      : `Wunsch von ${state.players[state.pendingMediaRequest.requester]}`;
  elements.mediaRequestPreviewText.textContent = state.pendingMediaRequest.text;
  if (awaiting && state.pendingMediaRequest.requester === state.activeIndex) {
    openMediaRequestFormForActivePlayer();
  } else {
    elements.mediaRequestForm.hidden = true;
  }
}

function renderSentMedia() {
  if (!state.pendingMedia) {
    elements.sentMediaPreview.hidden = true;
    if (elements.openSentMediaVault) elements.openSentMediaVault.hidden = true;
    return;
  }
  const sender = state.players[state.pendingMedia.sender];
  elements.sentMediaPreview.hidden = false;
  elements.sentMediaMeta.textContent = `Gesendet von ${sender}`;
  elements.sentMediaText.textContent = `${state.pendingMedia.name}${state.pendingMedia.caption ? ` - ${state.pendingMedia.caption}` : ""}. Verschluesselt in Privat gespeichert.`;
  if (elements.openSentMediaVault) elements.openSentMediaVault.hidden = !state.pendingMedia.vaultId;
}

function openVaultForSentMedia() {
  closeCategoryModal();
  setAppTab("vault");
  if (!vaultKey && elements.vaultPassword) elements.vaultPassword.focus();
}

function normalizeClipUrl(value) {
  const raw = String(value || "").trim();
  if (!raw) return "";
  const withProtocol = /^https?:\/\//i.test(raw) ? raw : `https://${raw}`;
  try {
    return new URL(withProtocol).href;
  } catch {
    return "";
  }
}

function startPornClipLink(focus = true) {
  elements.pornClipForm.hidden = false;
  if (focus) elements.pornClipUrl.focus();
}

function submitPornClipLink(event) {
  event.preventDefault();
  const url = normalizeClipUrl(elements.pornClipUrl.value);
  const reason = elements.pornClipReason.value.trim();
  if (!url) {
    elements.pornClipUrl.focus();
    return;
  }

  const category = getCategory("porn-clip");
  const action = category.actions.find((item) => item.id === "link") || { playerPoints: 20 };
  const log = todayLog();
  const doneKey = "porn-clip:link";
  const points = action.playerPoints;
  const alreadyDone = Boolean(log[doneKey]);
  state.pendingPornClip = {
    url,
    reason,
    sender: state.activeIndex,
    at: new Date().toISOString(),
    seenBy: [],
    reaction: null
  };

  if (!alreadyDone) {
    log[doneKey] = {
      player: state.activeIndex,
      at: new Date().toISOString(),
      visibleToPartner: elements.shareAcceptedTask.checked
    };
    addPoints(state.activeIndex, points);
    markPlayedThisWeek("porn-clip");
    updateDailyStreak();
  }

  currentTaskDraft = {
    title: "Porno-Link",
    text: reason ? `${url} - ${reason}` : url,
    tags: ["porn", "media", "message"]
  };
  learnFromTask("porn-clip", reason ? 2 : 1, currentTaskDraft);
  showAcceptedTask("porn-clip", { label: "Link gesendet", playerPoints: alreadyDone ? 0 : points });
  if (state.activeTask?.categoryId === "porn-clip") state.activeTask.pointsAwarded = true;
  elements.pornClipForm.hidden = true;
  saveState();
  renderPornClipPreview();
  renderDailyCategories();
  updateLabels();
}

function renderPornClipPreview() {
  if (!state.pendingPornClip) {
    elements.pornClipPreview.hidden = true;
    if (elements.pornClipReactionActions) elements.pornClipReactionActions.hidden = true;
    if (elements.pornClipReactionStatus) elements.pornClipReactionStatus.textContent = "";
    return;
  }

  const sender = state.players[state.pendingPornClip.sender];
  const seenBy = Array.isArray(state.pendingPornClip.seenBy) ? state.pendingPornClip.seenBy : [];
  const viewerHasSeen = seenBy.includes(state.activeIndex);
  const partnerCanReact = state.pendingPornClip.sender !== state.activeIndex && viewerHasSeen;
  const reaction = state.pendingPornClip.reaction;
  elements.pornClipPreview.hidden = false;
  elements.pornClipMeta.textContent = `Link von ${sender}`;
  elements.pornClipText.textContent = state.pendingPornClip.reason || "Ohne Beschreibung.";
  elements.pornClipLink.href = state.pendingPornClip.url;
  elements.pornClipLink.textContent = "Ansehen";
  if (elements.pornClipReactionActions) elements.pornClipReactionActions.hidden = !partnerCanReact;
  if (elements.pornClipReactionStatus) {
    elements.pornClipReactionStatus.textContent = reaction
      ? `${state.players[reaction.player] || "Partner"}: ${reaction.choice}`
      : partnerCanReact
        ? "Was machen wir damit?"
        : state.pendingPornClip.sender === state.activeIndex
          ? "Warte auf die Reaktion deines Partners."
          : "Erst ansehen, dann entscheiden.";
  }
}

function markPornClipSeen() {
  if (!state.pendingPornClip) return;
  const seenBy = new Set(Array.isArray(state.pendingPornClip.seenBy) ? state.pendingPornClip.seenBy : []);
  seenBy.add(state.activeIndex);
  state.pendingPornClip.seenBy = [...seenBy];
  saveState();
  renderPornClipPreview();
  renderTaskThread();
  void 0;
}

function setPornClipReaction(choice) {
  if (!state.pendingPornClip || state.pendingPornClip.sender === state.activeIndex) return;
  state.pendingPornClip.reaction = {
    player: state.activeIndex,
    choice,
    at: new Date().toISOString()
  };
  saveState();
  renderPornClipPreview();
  renderTaskThread();
  void 0;
}

function appendClipSiteLinks() {
  const links = document.createElement("div");
  links.className = "clip-links";
  clipSites.forEach((site) => {
    const link = document.createElement("a");
    link.href = site.url;
    link.target = "_blank";
    link.rel = "noopener noreferrer";
    link.textContent = site.label;
    links.append(link);
  });
  elements.delegatedTask.append(links);
}

function appendClipPointHint() {
  const category = getCategory("porn-clip");
  const watchAction = category.actions.find((item) => item.id === "watch") || { playerPoints: 20 };
  const hint = createPointPill(watchAction.playerPoints);
  elements.delegatedTask.append(hint);
}

function taskSuggestsMedia(task = currentTaskDraft) {
  if (!task) return false;
  const tags = task.tags || [];
  const text = `${task.title || ""} ${task.text || ""}`.toLowerCase();
  const hasMediaTarget = tags.some((tag) => ["photo", "video", "camera", "cam"].includes(tag)) || /foto|bild|video/.test(text);
  if (!hasMediaTarget) return false;
  if (/kein bild|keine bilder|ohne bild|nicht schick|nicht geschickt|nicht senden|nicht gesendet|nur beschreib|beschreib ein bild|bild im kopf|foto-wunsch|videowunsch|bildwunsch/.test(text)) {
    return false;
  }
  return /(schick|sende|sendet|mach|macht|dreh|dreht|nimm|nimmt|film|filmt|speicher|speichert).{0,90}(foto|bild|video)|(?:foto|bild|video).{0,90}(schick|sende|sendet|machen|mach|drehen|dreh|nimm|nimmt|film|filmt|speicher|speichert)/.test(text);
}

function taskSuggestsVoice(task = currentTaskDraft) {
  if (!task) return false;
  const tags = task.tags || [];
  const text = `${task.title || ""} ${task.text || ""}`.toLowerCase();
  return tags.includes("voice") || /sprachnotiz|sprachnachricht|stimme|audio/.test(text);
}

function appendVoiceRecorderLinkIfNeeded(task = currentTaskDraft, categoryId = "") {
  if (!taskSuggestsVoice(task) || !elements.delegatedTask || elements.delegatedTask.querySelector("[data-voice-recorder-link]")) return;
  const button = document.createElement("button");
  button.type = "button";
  button.className = "voice-recorder-link";
  button.dataset.voiceRecorderLink = "true";
  button.textContent = "Sprachnachricht hochladen";
  button.addEventListener("click", () => startMediaSend(categoryId || task.categoryId || "send-me"));
  elements.delegatedTask.append(button);
}

function updateMediaSendButtonLabel(button, task = currentTaskDraft) {
  if (!button) return;
  button.textContent = taskSuggestsVoice(task) && !taskSuggestsMedia(task)
    ? "Sprachnachricht senden"
    : "Bild/Video/Audio senden";
}

function createMediaSendButton(categoryId) {
  const button = document.createElement("button");
  button.type = "button";
  button.dataset.mediaSendButton = "true";
  updateMediaSendButtonLabel(button);
  button.addEventListener("click", () => startMediaSend(categoryId));
  return button;
}

function openCategory(categoryId) {
  const category = getCategory(categoryId);
  if (!category) return;

  const firstOpen = !hasSeenCategoryRule(categoryId);
  markCategoryRuleSeen(categoryId);
  saveState();

  elements.modalEyebrow.textContent = state.players[state.activeIndex];
  elements.modalTitle.textContent = category.title;
  const ruleText = "";
  elements.modalRule.textContent = ruleText;
  elements.modalRule.hidden = !ruleText;
  elements.shareAcceptedTask.checked = true;
  elements.delegatedTask.classList.remove("truth-dare-focus");
  resetWishUi();

  if (category.id !== "random" && !["wish", "thoughts", "send-me"].includes(category.id)) {
    const delegated = getDelegatedTask(category);
    renderDelegatedTask(delegated, category.id);
    if (!["wish", "send-me", "jennys-feet", "porn-clip"].includes(category.id)) appendPointHint(category);

    if (category.id === "porn-clip") {
      appendClipSiteLinks();
      appendClipPointHint();
    }
  }

  elements.modalActions.innerHTML = "";
  const log = todayLog();
  if (category.id === "position-generator") {
    const rerollButton = document.createElement("button");
    rerollButton.type = "button";
    rerollButton.textContent = "Zappen";
    rerollButton.addEventListener("click", () => {
      renderDelegatedTask(buildPositionTask(), category.id);
      appendPointHint(category);
    });

    const acceptButton = document.createElement("button");
    acceptButton.type = "button";
    acceptButton.textContent = "Aufgabe annehmen";
    acceptButton.addEventListener("click", () => acceptDailyCategory(category.id));

    elements.modalActions.append(rerollButton, acceptButton);
    elements.categoryModal.hidden = false;
    return;
  }

  if (category.id === "random") {
    let selectedTruthDare = "";
    let selectedTruthMode = normalizeTruthGameMode(state.truthGameMode || "");
    let truthDareDraws = [];
    let selectedDrawIndex = 0;
    let zapCount = 0;
    let accepted = false;
    const forcedChoice = forcedTruthDareChoice();
    const maxZaps = 5;
    const action = category.actions[0];
    currentTaskDraft = null;

    const setRandomActions = (...buttons) => {
      elements.modalActions.innerHTML = "";
      elements.modalActions.append(...buttons);
    };

    const renderIntro = () => {
      elements.delegatedTask.hidden = false;
      elements.delegatedTask.classList.add("truth-dare-focus");
      elements.delegatedTask.innerHTML = "";
      const choiceTitle = document.createElement("h3");
      const choiceText = document.createElement("p");
      choiceTitle.textContent = "Wahrheit oder Pflicht?";
      choiceText.textContent = forcedChoice
        ? `We2 gleicht aus: diesmal ${truthDareLabel(forcedChoice)}.`
        : "Waehle Wahrheit, Pflicht oder Ãœberraschung. Danach bleibt diese Runde dabei.";
      elements.delegatedTask.append(choiceTitle, choiceText);
      const availabilityContext = {
        ...truthDareActorContext(),
        choice: selectedTruthDare || forcedChoice || "surprise",
        modeId: selectedTruthMode
      };
      const availableModes = getAvailableShortGameModes(availabilityContext);
      const availableGameOptions = getAvailableGameOptions(availabilityContext);
      renderRandomModePicker(selectedTruthMode, (modeId) => {
        selectedTruthMode = normalizeTruthGameMode(modeId);
        state.truthGameMode = selectedTruthMode;
        selectedTruthDare = "";
        truthDareDraws = [];
        selectedDrawIndex = 0;
        zapCount = 0;
        accepted = false;
        currentTaskDraft = null;
        saveState();
        renderIntro();
      }, availableModes);
      const currentChoice = selectedTruthDare || forcedChoice || "surprise";
      const modeOption = availableModes.find((mode) => mode.id === selectedTruthMode) || null;
      const choiceAvailability = new Map(availableGameOptions.choices.map((item) => [item.id, item]));
      if (modeOption && !modeOption.available) {
        const note = document.createElement("p");
        note.className = "helper-text";
        note.textContent = "Fuer diesen Modus gibt es gerade keinen sauberen Treffer. Bitte einen anderen Modus waehlen.";
        elements.delegatedTask.append(note);
      } else if (!choiceAvailability.get(currentChoice)?.available) {
        const note = document.createElement("p");
        note.className = "helper-text";
        note.textContent = "Fuer diese Auswahl gibt es gerade keinen sauberen Treffer.";
        elements.delegatedTask.append(note);
      }
    };

    const appendTruthDareDrawChooser = () => {
      if (truthDareDraws.length < 2) return;
      const chooser = document.createElement("div");
      chooser.className = "truth-dare-draws";
      truthDareDraws.forEach((draw, index) => {
        const button = document.createElement("button");
        button.type = "button";
        button.className = index === selectedDrawIndex ? "primary" : "";
        button.textContent = `${index + 1}`;
        button.title = draw.title;
        button.addEventListener("click", () => {
          selectedDrawIndex = index;
          renderCurrentTruthDareCard();
          renderReadyTruthDareActions();
        });
        chooser.append(button);
      });
      elements.delegatedTask.append(chooser);
    };

    const renderCurrentTruthDareCard = () => {
      const draw = truthDareDraws[selectedDrawIndex];
      renderDelegatedTask(draw, category.id);
      elements.delegatedTask.classList.add("truth-dare-focus");
      appendTruthDareDrawChooser();
    };

    const appendTruthDareAnswerBox = (draw) => {
      if (draw.neutral) return;
      const form = document.createElement("form");
      const prompt = document.createElement("p");
      const input = document.createElement("textarea");
      const button = document.createElement("button");
      form.className = "truth-dare-answer";
      prompt.className = "helper-text";
      prompt.textContent = draw.type === "truth"
        ? (draw.answerRule || "Antwort ehrlich, aber liebevoll.")
        : (draw.safetyRule || "Kurz rueckmelden, dann weiter.");
      input.rows = 3;
      input.placeholder = draw.type === "truth" ? "Antwort notieren..." : "Reaktion, Plan oder Ergebnis notieren...";
      button.type = "submit";
      button.className = "primary";
      button.textContent = draw.type === "truth" ? "Antwort speichern" : "Senden";
      form.addEventListener("submit", (event) => {
        event.preventDefault();
        const text = input.value.trim();
        if (!text) return;
        if (draw.type === "truth") elements.shareAcceptedTask.checked = true;
        if (!accepted) {
          accepted = true;
          recordTruthDareChoice(draw.type || selectedTruthDare);
          registerPendingTruthDareDuty(draw.type || selectedTruthDare);
          acceptDailyCategory(category.id, { stayInModal: true, deferProgress: draw.type === "truth" });
          if (draw.type !== "truth") renderAcceptedTruthDareActions();
        }
        if (draw.type === "truth") {
          completeTruthAnswerTask(category.id, draw, text, action);
          return;
        }
        addTaskComment(`Pflicht: ${text}`, draw.type);
        input.value = "";
      });
      form.append(prompt, input, button);
      elements.delegatedTask.append(form);
    };

    const renderNeutralTruthDareActions = () => {
      const changeModeButton = document.createElement("button");
      changeModeButton.type = "button";
      changeModeButton.className = "primary";
      changeModeButton.textContent = "Modus wechseln";
      changeModeButton.addEventListener("click", () => {
        selectedTruthDare = "";
        truthDareDraws = [];
        selectedDrawIndex = 0;
        zapCount = 0;
        accepted = false;
        renderIntro();
        setRandomActions(truthButton, dareButton, surpriseButton);
      });
      setRandomActions(changeModeButton, truthButton, dareButton, surpriseButton);
    };

    const renderReadyTruthDareActions = () => {
      const activeDraw = truthDareDraws[selectedDrawIndex];
      if (activeDraw?.neutral) {
        renderNeutralTruthDareActions();
        return;
      }
      const buttons = [];
      if (zapCount < maxZaps) {
        const zapButton = document.createElement("button");
        zapButton.type = "button";
        zapButton.textContent = "Zappen";
        zapButton.addEventListener("click", () => {
          zapCount += 1;
          truthDareDraws.push(buildTruthOrDareTask(selectedTruthDare, selectedTruthMode));
          selectedDrawIndex = truthDareDraws.length - 1;
          renderCurrentTruthDareCard();
          renderReadyTruthDareActions();
        });
        buttons.push(zapButton);
      }

      if (taskSuggestsMedia() || taskSuggestsVoice()) {
        buttons.push(createMediaSendButton(category.id));
      }

      const acceptButton = document.createElement("button");
      acceptButton.type = "button";
      acceptButton.className = "primary";
      acceptButton.textContent = "Aufgabe annehmen";
      acceptButton.addEventListener("click", () => {
        if (accepted) return;
        accepted = true;
        const activeDraw = truthDareDraws[selectedDrawIndex];
        recordTruthDareChoice(activeDraw?.type || selectedTruthDare);
        registerPendingTruthDareDuty(activeDraw?.type || selectedTruthDare);
        acceptDailyCategory(category.id, { stayInModal: true, deferProgress: activeDraw?.type === "truth" });
        renderCurrentTruthDareCard();
        appendTruthDareAnswerBox(activeDraw || {});
        renderAcceptedTruthDareActions();
      });
      buttons.push(acceptButton);
      setRandomActions(...buttons);
    };

    const renderAcceptedTruthDareActions = () => {
      const doneButton = document.createElement("button");
      doneButton.type = "button";
      doneButton.className = "primary";
      doneButton.textContent = "Erledigt";
      doneButton.addEventListener("click", () => {
        completePendingTruthDareDuty();
        if (currentTaskIsSolo(category.id)) {
          completeDailyCategory(category.id, action);
        } else {
          completeDailyCategoryForBoth(category.id, action);
        }
      });
      setRandomActions(doneButton);
    };

    const chooseTruthDare = (choice) => {
      const actualChoice = choice === "surprise"
        ? (forcedChoice || choice)
        : (forcedChoice && choice !== forcedChoice ? forcedChoice : choice);
      if (forcedChoice && choice !== "surprise" && choice !== forcedChoice) return;
      const pickedCard = pickCardForSelection({ choice: actualChoice, modeId: selectedTruthMode, drawerIndex: state.activeIndex }, truthDareActorContext());
      if (!pickedCard) {
        selectedTruthDare = choice;
        truthDareDraws = [buildNeutralTruthDareCard(actualChoice, selectedTruthMode)];
        selectedDrawIndex = 0;
        zapCount = 0;
        accepted = false;
        renderCurrentTruthDareCard();
        renderReadyTruthDareActions();
        return;
      }
      selectedTruthDare = choice;
      truthDareDraws = [buildTruthOrDareTask(actualChoice, selectedTruthMode)];
      selectedDrawIndex = 0;
      zapCount = 0;
      accepted = false;
      renderCurrentTruthDareCard();
      renderReadyTruthDareActions();
    };

    const truthButton = document.createElement("button");
    truthButton.type = "button";
    truthButton.textContent = "Wahrheit";
    truthButton.className = forcedChoice === "truth" ? "primary" : "";
    truthButton.disabled = forcedChoice === "dare" || !pickCardForSelection({ choice: "truth", modeId: selectedTruthMode, drawerIndex: state.activeIndex }, truthDareActorContext());
    truthButton.addEventListener("click", () => chooseTruthDare("truth"));

    const dareButton = document.createElement("button");
    dareButton.type = "button";
    dareButton.textContent = "Pflicht";
    dareButton.className = forcedChoice === "dare" ? "primary" : "";
    dareButton.disabled = forcedChoice === "truth" || !pickCardForSelection({ choice: "dare", modeId: selectedTruthMode, drawerIndex: state.activeIndex }, truthDareActorContext());
    dareButton.addEventListener("click", () => chooseTruthDare("dare"));

    const surpriseButton = document.createElement("button");
    surpriseButton.type = "button";
    surpriseButton.textContent = "Ãœberraschung";
    surpriseButton.disabled = !pickCardForSelection({ choice: "surprise", modeId: selectedTruthMode, drawerIndex: state.activeIndex }, truthDareActorContext());
    surpriseButton.addEventListener("click", () => chooseTruthDare("surprise"));

    renderIntro();
    setRandomActions(truthButton, dareButton, surpriseButton);
    elements.categoryModal.hidden = false;
    return;
  }

  if (category.id === "wish") {
    hideDelegatedTask();
    renderWishOffer();
    elements.categoryModal.hidden = false;
    startWishOffer();
    return;
  }

  if (category.id === "thoughts") {
    hideDelegatedTask();
    renderThoughtPreview();

    const ownButton = document.createElement("button");
    ownButton.type = "button";
    ownButton.className = "primary";
    ownButton.textContent = "GesprÃ¤ch starten";
    ownButton.addEventListener("click", startOwnThought);

    const promptButton = document.createElement("button");
    promptButton.type = "button";
    promptButton.textContent = "Vorgabe ziehen";
    promptButton.addEventListener("click", chooseThoughtPrompt);

    elements.modalActions.append(ownButton, promptButton);
    elements.categoryModal.hidden = false;
    return;
  }

  if (category.id === "send-me") {
    hideDelegatedTask();
    elements.modalRule.textContent = "";
    elements.modalRule.hidden = true;

    const requestButton = document.createElement("button");
    requestButton.type = "button";
    requestButton.textContent = "Wunschanfrage";
    requestButton.addEventListener("click", startMediaRequest);

    const randomButton = document.createElement("button");
    randomButton.type = "button";
    randomButton.className = "primary";
    randomButton.textContent = "App gibt vor";
    randomButton.addEventListener("click", chooseRandomMediaPrompt);

    const mediaButton = document.createElement("button");
    mediaButton.type = "button";
    mediaButton.textContent = "Selbst Regie";
    mediaButton.addEventListener("click", () => startMediaSend("send-me"));
    elements.modalActions.append(randomButton, requestButton, mediaButton);
    renderMediaRequest();
    renderSentMedia();
    elements.categoryModal.hidden = false;
    return;
  }

  if (category.id === "porn-clip") {
    const doneButton = document.createElement("button");
    const action = category.actions.find((item) => item.id === "watch") || getExecutionAction(category);
    doneButton.type = "button";
    doneButton.className = "primary";
    doneButton.textContent = "Erledigt";
    doneButton.addEventListener("click", () => completeDailyCategoryForBoth(category.id, action));

    startPornClipLink(false);
    elements.modalActions.append(doneButton);
    renderPornClipPreview();
    elements.categoryModal.hidden = false;
    return;
  }

  if (category.id === "jennys-feet") {
    refreshPointHint(category);

    const syncFootMediaButton = (button) => {
      if (!button) return;
      updateMediaSendButtonLabel(button, currentTaskDraft);
      button.hidden = !(taskSuggestsMedia(currentTaskDraft) || taskSuggestsVoice(currentTaskDraft));
    };

    const zappButton = document.createElement("button");
    zappButton.type = "button";
    zappButton.textContent = "Zappen";
    zappButton.addEventListener("click", () => {
      renderDelegatedTask(getDelegatedTask(category), category.id);
      refreshPointHint(category);
      syncFootMediaButton(mediaButton);
    });

    const moreButton = document.createElement("button");
    moreButton.type = "button";
    moreButton.textContent = "Verlängern";
    moreButton.addEventListener("click", () => {
      appendFootContinuation(category);
      syncFootMediaButton(mediaButton);
    });

    const mediaButton = createMediaSendButton(category.id);
    syncFootMediaButton(mediaButton);

    const acceptButton = document.createElement("button");
    acceptButton.type = "button";
    acceptButton.textContent = "Aufgabe annehmen";
    acceptButton.addEventListener("click", () => acceptDailyCategory(category.id));

    const doneButton = document.createElement("button");
    const action = getExecutionAction(category);
    doneButton.type = "button";
    doneButton.className = "primary";
    doneButton.textContent = "Erledigt";
    doneButton.title = action.label;
    doneButton.addEventListener("click", () => {
      if (!ensureActiveTaskFromModal(category.id)) return;
      if (currentTaskIsSolo(category.id)) {
        completeDailyCategory(category.id, action);
      } else {
        completeDailyCategoryForBoth(category.id, action);
      }
    });

    elements.modalActions.append(zappButton, acceptButton);
    elements.categoryModal.hidden = false;
    return;
  }

  const zappButton = document.createElement("button");
  const acceptButton = document.createElement("button");
  const action = getExecutionAction(category);
  const doneButton = document.createElement("button");
  const mediaButton = createMediaSendButton(category.id);
  const syncMediaButton = () => {
    updateMediaSendButtonLabel(mediaButton, currentTaskDraft);
    mediaButton.hidden = !(taskSuggestsMedia(currentTaskDraft) || taskSuggestsVoice(currentTaskDraft));
  };
  syncMediaButton();

  zappButton.type = "button";
  zappButton.textContent = "Zappen";
  zappButton.addEventListener("click", () => {
    renderDelegatedTask(getDelegatedTask(category), category.id);
    appendPointHint(category);
    syncMediaButton();
  });

  acceptButton.type = "button";
  acceptButton.textContent = "Aufgabe annehmen";
  acceptButton.addEventListener("click", () => acceptDailyCategory(category.id));

  doneButton.type = "button";
  doneButton.className = "primary";
  doneButton.textContent = "Erledigt";
  doneButton.title = action.label;
  doneButton.addEventListener("click", () => {
    if (!ensureActiveTaskFromModal(category.id)) return;
    if (currentTaskIsSolo(category.id)) {
      completeDailyCategory(category.id, action);
    } else {
      completeDailyCategoryForBoth(category.id, action);
    }
  });

  if (category.id === "thoughts") {
    elements.modalActions.append(acceptButton);
  } else {
    elements.modalActions.append(zappButton, acceptButton);
  }

  elements.categoryModal.hidden = false;
}

function closeCategoryModal() {
  elements.categoryModal.hidden = true;
}

function showAcceptedTask(categoryId, action) {
  const category = getCategory(categoryId);
  const actor = state.players[state.activeIndex];
  const visible = elements.shareAcceptedTask.checked;
  createSharedTask(categoryId, action, visible);
  if (state.activeTask) {
    state.activeTask.status = "active";
    state.activeTask.expanded = true;
    state.activeTask.visible = true;
    state.activeTask.secretForPartner = !visible;
  }
  dashboardTaskListOpen = true;
  elements.taskStatus.hidden = false;
  elements.taskStatusText.textContent = visible
    ? `Aktiv: ${actor} startet ${category.title}`
    : `Aktiv: ${actor} startet geheim`;
  if (elements.nextFootTask) elements.nextFootTask.hidden = true;
  setAppTab("tasks");
  renderTaskThread();
  void 0;
}

function ensureActiveTaskFromModal(categoryId, options = {}) {
  if (state.activeTask && state.activeTask.categoryId === categoryId) return true;
  acceptDailyCategory(categoryId, options);
  return false;
}

function acceptDailyCategory(categoryId, options = {}) {
  const category = getCategory(categoryId);
  const log = todayLog();
  const acceptedKey = `${categoryId}:accepted:${Date.now()}`;
  const executionAction = getExecutionAction(category);
  log[acceptedKey] = {
    player: state.activeIndex,
    at: new Date().toISOString(),
    visibleToPartner: elements.shareAcceptedTask.checked
  };
  learnFromTask(categoryId, 1);
  if (!options.deferProgress) markPlayedThisWeek(categoryId);
  showAcceptedTask(categoryId, { ...executionAction, label: "angenommen" });
  if (state.activeTask) {
    state.activeTask.status = "active";
    state.activeTask.expanded = true;
    state.activeTask.visible = true;
  }
  dashboardTaskListOpen = true;
  saveState();
  renderDailyCategories();
  updateLabels();
  if (!options.stayInModal) {
    closeCategoryModal();
    if (state.activeTask) state.activeTask.expanded = true;
    setAppTab("tasks");
    renderTaskThread();
  }
}

function completeDailyCategoryForBoth(categoryId, action) {
  const category = getCategory(categoryId);
  const log = todayLog();
  const doneKey = `${categoryId}:executed:${Date.now()}`;

  log[doneKey] = {
    player: state.activeIndex,
    at: new Date().toISOString(),
    visibleToPartner: elements.shareAcceptedTask.checked
  };
  addPoints(0, action.playerPoints);
  addPoints(1, action.playerPoints);
  learnFromTask(categoryId, 3);
  markPlayedThisWeek(categoryId);
  updateDailyStreak();
  finishSharedTask(categoryId, action, elements.shareAcceptedTask.checked);
  elements.taskStatus.hidden = false;
  elements.taskStatusText.textContent = `"${category.title}" ausgefuehrt. Beide bekommen ${action.playerPoints}.`;
  advanceRound();
  saveState();
  renderDailyCategories();
  closeCategoryModal();
}

function completeTruthAnswerTask(categoryId, draw, answer, action) {
  const category = getCategory(categoryId);
  const points = Number(action?.playerPoints) || Number(getExecutionAction(category).playerPoints) || 0;
  const now = new Date().toISOString();
  const player = state.activeIndex;
  const isSolo = currentTaskIsSolo(categoryId);
  const question = String(draw?.text || currentTaskDraft?.text || "").trim();
  const answerText = String(answer || "").trim();
  const title = String(draw?.title || currentTaskDraft?.title || "Wahrheit").trim();
  const tags = [...new Set([...(currentTaskDraft?.tags || []), ...(draw?.tags || []), "truth"])];
  const taskText = `Frage: ${question}\n\nAntwort: ${answerText}`;
  const log = todayLog();
  const doneKey = `${categoryId}:truth:${Date.now()}`;

  log[doneKey] = {
    player,
    at: now,
    visibleToPartner: true,
    awaitingPartnerApproval: true
  };

  currentTaskDraft = {
    ...(currentTaskDraft || {}),
    categoryId,
    title,
    text: taskText,
    steps: [],
    tags
  };

  if (!state.activeTask || state.activeTask.categoryId !== categoryId) {
    createSharedTask(categoryId, { label: "Wahrheit beantwortet", playerPoints: points }, true);
  }

  if (state.activeTask) {
    state.activeTask.title = title;
    state.activeTask.text = taskText;
    state.activeTask.steps = [];
    state.activeTask.tags = tags;
    state.activeTask.visible = true;
    state.activeTask.secretForPartner = false;
    state.activeTask.status = "active";
    state.activeTask.expanded = true;
    state.activeTask.truthAnswered = true;
    state.activeTask.truthQuestion = question;
    state.activeTask.truthAnswer = answerText;
    state.activeTask.truthAnsweredAt = now;
    state.activeTask.truthAnswerPlayer = player;
    state.activeTask.truthAwaitingPartnerApproval = true;
    state.activeTask.pointValue = points;
    state.activeTask.pointLabel = "Aufgabe bestanden";
    state.activeTask.pointsForBoth = !isSolo;
    state.activeTask.comments = [
      {
        type: "system",
        player,
        text: `${state.players[player]} hat Wahrheit beantwortet.`,
        at: now
      }
    ];
  }

  elements.taskStatus.hidden = false;
  const partner = state.players[player === 0 ? 1 : 0] || "Dein Partner";
  elements.taskStatusText.textContent = `Wahrheit gesendet. ${partner} entscheidet Ã¼ber "Aufgabe bestanden".`;
  closeCategoryModal();
  saveState();
  renderDailyCategories();
  updateLabels();
  setAppTab("tasks");
  renderTaskThread();
  void 0;
}

function completeTruthAnswerCategory(categoryId, action) {
  if (currentTaskIsSolo(categoryId)) {
    completeDailyCategory(categoryId, action);
  } else {
    completeDailyCategoryForBoth(categoryId, action);
  }
  markTruthTaskForPartnerAutoClear();
  if (state.activeTask) state.activeTask.expanded = true;
  saveState();
  renderTaskThread();
}

function openFootFollowUp() {
  elements.categoryModal.hidden = false;
  elements.modalEyebrow.textContent = state.players[state.activeIndex];
  elements.modalTitle.textContent = "Fußaufgabe";
  elements.modalRule.hidden = true;
  elements.wishForm.hidden = true;
  elements.wishOffer.hidden = true;
  elements.thoughtForm.hidden = true;
  elements.thoughtPreview.hidden = true;
  elements.mediaSendForm.hidden = true;
  elements.mediaRequestForm.hidden = true;
  elements.mediaRequestPreview.hidden = true;
  elements.sentMediaPreview.hidden = true;
  elements.shareAcceptedTask.checked = true;
  elements.delegatedTask.hidden = false;
  elements.delegatedTask.innerHTML = "";
  const task = buildFootTask();
  const title = document.createElement("h3");
  const text = document.createElement("p");
  const taskText = applyLanguageStyle(task.title, compactTaskText(task.text, task.tags || []), task.tags || []);
  title.textContent = task.title;
  text.textContent = taskText;
  elements.delegatedTask.append(title, text);
  currentTaskDraft = {
    ...task,
    text: taskText,
    steps: [],
    tags: task.tags || []
  };
  elements.modalActions.innerHTML = "";
  const more = document.createElement("button");
  more.type = "button";
  more.textContent = "Verlängern";
  more.addEventListener("click", () => {
    appendFootContinuation(getCategory("jennys-feet"));
      if ((taskSuggestsMedia(currentTaskDraft) || taskSuggestsVoice(currentTaskDraft)) && !elements.modalActions.querySelector("[data-media-send-button]")) {
        elements.modalActions.insertBefore(createMediaSendButton("jennys-feet"), accept);
      }
    });
  const mediaButton = (taskSuggestsMedia(currentTaskDraft) || taskSuggestsVoice(currentTaskDraft)) ? createMediaSendButton("jennys-feet") : null;
  const accept = document.createElement("button");
  accept.type = "button";
  accept.className = "primary";
  accept.textContent = "Aufgabe annehmen";
  accept.addEventListener("click", () => {
    currentTaskDraft = {
      ...currentTaskDraft,
      title: currentTaskDraft.title || task.title,
      text: currentTaskDraft.text || taskText
    };
    learnFromTask("jennys-feet", 2, currentTaskDraft);
    showAcceptedTask("jennys-feet", { label: "Fußaufgabe angenommen", playerPoints: 25 });
    advanceRound();
    saveState();
    renderDailyCategories();
  });
  elements.modalActions.append(...[more, mediaButton, accept].filter(Boolean));
}

function completeDailyCategory(categoryId, action) {
  const category = getCategory(categoryId);
  const log = todayLog();
  const doneKey = `${categoryId}:${action.id}:${Date.now()}`;

  log[doneKey] = {
    player: state.activeIndex,
    at: new Date().toISOString(),
    visibleToPartner: elements.shareAcceptedTask.checked
  };
  addPoints(state.activeIndex, action.playerPoints);
  learnFromTask(categoryId, 2);
  markPlayedThisWeek(categoryId);
  updateDailyStreak();
  finishSharedTask(categoryId, action, elements.shareAcceptedTask.checked);
  elements.taskStatus.hidden = false;
  elements.taskStatusText.textContent = `${state.players[state.activeIndex]} hat "${category.title}" ausgefuehrt und bekommt ${action.playerPoints}.`;
  advanceRound();
  saveState();
  renderDailyCategories();
  closeCategoryModal();
}

function claimReward() {
  const nextRewardAt = (state.rewardsClaimed + 1) * 100;
  if (getTotalPoints() < nextRewardAt) return;
  const reward = rewardForIndex(state.rewardsClaimed);
  state.rewardsClaimed += 1;
  saveState();
  updateLabels();
  alert(`Belohnung freigeschaltet: ${reward}`);
}

function ensureCardCompletionPanel() {
  let panel = document.querySelector("#cardCompletionPanel");
  if (panel) return panel;
  panel = document.createElement("div");
  panel.id = "cardCompletionPanel";
  panel.className = "card-completion-panel";
  if (elements.cardText?.isConnected) {
    elements.cardText.insertAdjacentElement("afterend", panel);
  } else if (elements.gameBoard) {
    elements.gameBoard.append(panel);
  }
  return panel;
}

function clearCardCompletionPanel() {
  const panel = document.querySelector("#cardCompletionPanel");
  if (!panel) return;
  if (typeof panel._cleanup === "function") panel._cleanup();
  panel.innerHTML = "";
  panel.hidden = true;
}

function updateCardActionState(phase) {
  if (!elements.drawCard || !elements.completeCard || !elements.skipCard) return;
  if (elements.gameBoard) elements.gameBoard.classList.toggle("card-focus-mode", phase === "preview" || phase === "in_progress");
  elements.drawCard.classList.remove("primary");
  if (phase === "preview") {
    elements.drawCard.hidden = true;
    elements.completeCard.hidden = false;
    elements.completeCard.textContent = "Aufgabe annehmen";
    elements.completeCard.classList.add("primary");
    elements.skipCard.hidden = false;
    elements.skipCard.textContent = "Zappen";
    return;
  }
  if (phase === "in_progress") {
    elements.drawCard.hidden = true;
    elements.completeCard.hidden = false;
    elements.completeCard.textContent = "Erledigt";
    elements.completeCard.classList.add("primary");
    elements.skipCard.hidden = false;
    elements.skipCard.textContent = "Abbrechen";
    return;
  }
  if (phase === "completed") {
    elements.drawCard.hidden = false;
    elements.drawCard.textContent = "Nächste Karte";
    elements.drawCard.classList.add("primary");
    elements.completeCard.hidden = true;
    elements.skipCard.hidden = true;
    return;
  }
  elements.drawCard.hidden = false;
  elements.drawCard.textContent = "Karte ziehen";
  elements.completeCard.hidden = true;
  elements.skipCard.hidden = true;
}

function feedbackButtonsForCard(session) {
  const items = [
    ["Mehr davon", "more"],
    ["Langsamer rantasten", "slower"],
    ["Thema oefter", "often"],
    ["Thema seltener", "rare"],
    ["Nur Gespraech", "talk"],
    ["Privat behalten", "private"]
  ];
  return items.map(([label, value]) => {
    const button = document.createElement("button");
    button.type = "button";
    button.textContent = label;
    button.addEventListener("click", () => {
      session.feedback = value;
      const tags = Array.isArray(session.card?.feedbackTags) ? session.card.feedbackTags : [];
      const delta = value === "more" ? 2 : value === "slower" ? 1 : value === "often" ? 1 : value === "rare" ? -1 : value === "talk" ? 0 : 0;
      tags.forEach((tag) => {
        if (!state.learnedTags || typeof state.learnedTags !== "object") state.learnedTags = {};
        state.learnedTags[tag] = Math.max(0, Math.min(20, Number(state.learnedTags[tag] || 0) + delta));
      });
      state.currentCardSession = session;
      state.cardSessions = (state.cardSessions || []).map((entry) => entry.sessionId === session.sessionId ? session : entry);
      saveState();
      renderCardCompletion(session.card, session);
    });
    return button;
  });
}

function mediaAcceptForCompletionType(completionType = "") {
  if (completionType === "audio") return "audio/*";
  if (completionType === "video") return "video/*";
  return "image/*";
}

async function ensureCardCompletionVaultKey(password = "") {
  if (vaultKey) return vaultKey;
  const key = await getVerifiedVaultKey(password);
  vaultKey = key;
  if (elements.vaultStatus) elements.vaultStatus.textContent = "Private Bibliothek offen. Neue Medien werden verschluesselt gespeichert.";
  if (elements.mediaInput) elements.mediaInput.disabled = false;
  if (elements.lockVault) elements.lockVault.disabled = false;
  await renderMedia().catch(() => {});
  return key;
}

async function saveCardCompletionMediaFile({ file, caption = "", session, normalized, password = "", visibleToPartner = true }) {
  const key = await ensureCardCompletionVaultKey(password);
  const record = await saveEncryptedMediaFile(file, {
    savedFrom: "card_completion",
    source: "card_completion",
    relatedCardId: normalized.id,
    relatedCardTitle: normalized.title,
    relatedCardType: normalized.type,
    relatedTopic: normalized.topic,
    relatedMode: normalized.mode,
    relatedIntensity: normalized.intensity,
    sessionId: session.sessionId,
    createdBy: state.activeIndex,
    sender: state.activeIndex,
    senderName: state.players[state.activeIndex],
    visibility: visibleToPartner ? "match" : "private",
    visibleToPartner,
    libraryCategory: normalized.libraryCategory,
    caption,
    taskText: normalized.text || ""
  }, key);
  session.completionData = {
    ...(session.completionData || {}),
    caption,
    mediaIds: [...new Set([...(session.completionData?.mediaIds || []), record.id])],
    mediaSaved: true
  };
  session.completionDataIds = [...new Set([...(session.completionDataIds || []), record.id])];
  state.currentCardSession = session;
  state.cardSessions = (state.cardSessions || []).filter((entry) => entry.sessionId !== session.sessionId).concat(session);
  saveState();
  return record;
}

function renderCardPreview(card, session) {
  const normalized = normalizeCardCompletion(card);
  const resolvedText = applyLanguageStyle(normalized.title, compactTaskText(normalized.text, normalized.tags || []), normalized.tags || []);
  const topicLabel = normalized.topic ? (categoryNames[normalized.topic] || normalized.topic) : (categoryNames[normalized.category] || normalized.category || "Karte");
  const modeLabel = CARD_MODE_CONFIG[normalized.mode]?.label || truthGameModeLabel(normalized.mode) || "Standard";
  elements.cardCategory.textContent = `${topicLabel} Â· ${modeLabel} Â· ${normalized.completionType}`;
  elements.cardTitle.textContent = normalized.title;
  elements.cardText.textContent = resolvedText;
  const panel = ensureCardCompletionPanel();
  if (typeof panel._cleanup === "function") panel._cleanup();
  panel.hidden = true;
  panel.innerHTML = "";
  state.currentCardSession = session || buildCardSession(normalized, buildCardDrawContext({ modeId: normalized.mode, topic: normalized.topic }));
  updateCardActionState("preview");
  if (elements.gameBoard) elements.gameBoard.classList.add("card-focus-mode");
}

function renderCardCompletion(card, session = state.currentCardSession) {
  if (!session) return;
  const normalized = normalizeCardCompletion(card || session.card || {});
  const panel = ensureCardCompletionPanel();
  panel.hidden = false;
  panel.innerHTML = "";
  if (typeof panel._cleanup === "function") panel._cleanup();
  const cleanup = [];
  panel._cleanup = () => cleanup.splice(0).forEach((fn) => {
    try {
      fn();
    } catch (error) {
      void error;
    }
  });

  const lead = document.createElement("p");
  lead.className = "card-completion-hint";
  lead.textContent = normalized.completionInstructions;
  panel.append(lead);

  const setSessionData = (data) => {
    session.completionData = { ...(session.completionData || {}), ...data };
    state.currentCardSession = session;
    state.cardSessions = (state.cardSessions || []).filter((entry) => entry.sessionId !== session.sessionId).concat(session);
    saveState();
  };

  if (normalized.completionType === "text") {
    const textarea = document.createElement("textarea");
    textarea.rows = 4;
    textarea.placeholder = "Antwort hier eingeben";
    textarea.value = session.completionData?.text || "";
    textarea.addEventListener("input", () => setSessionData({ text: textarea.value }));
    panel.append(textarea);
  } else if (normalized.completionType === "choice") {
    const choices = normalized.choices.length ? normalized.choices : ["Ja", "Spaeter", "Nein"];
    const choiceRow = document.createElement("div");
    choiceRow.className = "card-choice-row";
    choices.forEach((choice) => {
      const button = document.createElement("button");
      button.type = "button";
      button.textContent = choice.label || choice.title || choice;
      button.className = session.completionData?.choice === (choice.id || choice) ? "primary" : "";
      button.addEventListener("click", () => {
        setSessionData({ choice: choice.id || choice });
        renderCardCompletion(normalized, session);
      });
      choiceRow.append(button);
    });
    panel.append(choiceRow);
  } else if (normalized.completionType === "timer") {
    const timerState = session.completionData?.timerState || { running: false, startedAt: "", elapsedMs: 0 };
    const timer = document.createElement("div");
    timer.className = "card-timer";
    const timeLabel = document.createElement("strong");
    const elapsed = timerState.running && timerState.startedAt
      ? timerState.elapsedMs + (Date.now() - new Date(timerState.startedAt).getTime())
      : timerState.elapsedMs || 0;
    timeLabel.textContent = `${Math.max(0, Math.round(elapsed / 1000))}s`;
    const startButton = document.createElement("button");
    startButton.type = "button";
    startButton.textContent = timerState.running ? "Pause" : "Start";
    startButton.addEventListener("click", () => {
      const nextRunning = !timerState.running;
      const nextElapsed = nextRunning && timerState.startedAt
        ? timerState.elapsedMs
        : timerState.elapsedMs + (timerState.running && timerState.startedAt ? (Date.now() - new Date(timerState.startedAt).getTime()) : 0);
      setSessionData({
        timerState: {
          running: nextRunning,
          startedAt: nextRunning ? new Date().toISOString() : "",
          elapsedMs: nextElapsed
        }
      });
      renderCardCompletion(normalized, session);
    });
    timer.append(timeLabel, startButton);
    panel.append(timer);
  } else if (["photo", "video", "audio"].includes(normalized.completionType) || (normalized.completionType === "mixed" && (normalized.requiredInputs || []).some((kind) => ["photo", "video", "audio"].includes(kind)))) {
    const mediaKinds = normalized.completionType === "mixed"
      ? (normalized.requiredInputs || []).filter((kind) => ["photo", "video", "audio"].includes(kind))
      : [normalized.completionType];
    const mediaWrap = document.createElement("div");
    mediaWrap.className = "card-media-completion";
    const hint = document.createElement("p");
    hint.textContent = mediaKinds.length > 1
      ? "WÃ¤hlt die benoetigten Medien aus und speichert sie in der Bibliothek."
      : `${normalized.completionInstructions} Danach koennt ihr die Karte abschliessen.`;
    mediaWrap.append(hint);

    const preview = document.createElement("div");
    preview.className = "card-media-preview";
    const status = document.createElement("p");
    status.className = "card-completion-hint";
    const caption = document.createElement("input");
    caption.type = "text";
    caption.placeholder = "Optionale Notiz fuer die Bibliothek";
    caption.value = session.completionData?.caption || "";
    const password = document.createElement("input");
    password.type = "password";
    password.placeholder = "Privates Passwort";
    const unlockButton = document.createElement("button");
    unlockButton.type = "button";
    unlockButton.textContent = vaultKey ? "Privat offen" : "Privat oeffnen";
    const fileInput = document.createElement("input");
    fileInput.type = "file";
    fileInput.accept = mediaAcceptForCompletionType(normalized.completionType === "mixed" ? (mediaKinds[0] || "photo") : normalized.completionType);
    const saveButton = document.createElement("button");
    saveButton.type = "button";
    saveButton.textContent = "In Bibliothek speichern";

    const existingIds = new Set(session.completionDataIds || []);
    const savedCount = existingIds.size;
    const savedLabel = document.createElement("p");
    savedLabel.className = "card-completion-hint";
    savedLabel.textContent = savedCount ? `${savedCount} Datei(en) gespeichert.` : "Noch keine Datei gespeichert.";

    let selectedFile = null;
    let previewUrl = "";
    const renderPreview = () => {
      preview.innerHTML = "";
      if (previewUrl) {
        cleanup.push(() => URL.revokeObjectURL(previewUrl));
      }
      if (!selectedFile) {
        preview.textContent = "Noch keine Datei ausgewaehlt.";
        return;
      }
      const url = URL.createObjectURL(selectedFile);
      previewUrl = url;
      cleanup.push(() => URL.revokeObjectURL(url));
      const media = selectedFile.type.startsWith("video/")
        ? document.createElement("video")
        : selectedFile.type.startsWith("audio/")
          ? document.createElement("audio")
          : document.createElement("img");
      media.src = url;
      if (media.tagName === "VIDEO" || media.tagName === "AUDIO") media.controls = true;
      media.alt = selectedFile.name;
      media.className = "card-media-preview-media";
      const label = document.createElement("strong");
      label.textContent = selectedFile.name;
      preview.append(media, label);
    };

    const setStatus = (text) => {
      status.textContent = text;
    };

    fileInput.addEventListener("change", () => {
      selectedFile = fileInput.files?.[0] || null;
      renderPreview();
      setStatus(selectedFile ? `AusgewÃ¤hlt: ${selectedFile.name}` : "Noch keine Datei ausgewaehlt.");
    });

    unlockButton.addEventListener("click", async () => {
      if (vaultKey) {
        setStatus("Private Bibliothek ist offen.");
        return;
      }
      try {
        await ensureCardCompletionVaultKey(password.value.trim());
        password.value = "";
        unlockButton.textContent = "Privat offen";
        setStatus("Private Bibliothek ist offen.");
      } catch (error) {
        setStatus(error.message || "Privates Passwort passt nicht.");
      }
    });

    saveButton.addEventListener("click", async () => {
      if (!selectedFile) {
        setStatus("Bitte zuerst eine Datei auswaehlen.");
        return;
      }
      try {
        await saveCardCompletionMediaFile({
          file: selectedFile,
          caption: caption.value.trim(),
          session,
          normalized,
          password: password.value.trim(),
          visibleToPartner: true
        });
        setStatus("Datei verschluesselt gespeichert.");
        renderCardCompletion(normalized, session);
      } catch (error) {
        setStatus(error.message || "Die Datei konnte nicht gespeichert werden.");
      }
    });

    renderPreview();
    mediaWrap.append(caption, fileInput, preview, savedLabel, password, unlockButton, saveButton, status);
    panel.append(mediaWrap);
  } else {
    const info = document.createElement("p");
    info.textContent = "Wenn ihr bereit seid, markiert die Karte als erledigt.";
    panel.append(info);
  }

  if (session.status === "completed") {
    const feedbackWrap = document.createElement("div");
    feedbackWrap.className = "card-feedback-row";
    feedbackButtonsForCard(session).forEach((button) => feedbackWrap.append(button));
    panel.append(feedbackWrap);
  }

  updateCardActionState(session.status === "completed" ? "completed" : "in_progress");
}

function finaliseCardSession(session, outcome = "completed") {
  if (!session) return;
  const now = new Date().toISOString();
  session.status = outcome;
  if (outcome === "completed") {
    session.completedAt = now;
    if (session.card?.feedbackTags?.length) {
      learnFromTask(session.card.category || session.topic || "talk", 1, session.card);
    }
  }
  if (outcome === "skipped" || outcome === "too_much") {
    session.completedAt = now;
  }
  if (outcome === "aborted") {
    session.abortedAt = now;
  }
  state.currentCardSession = session;
  state.cardSessions = (state.cardSessions || []).filter((entry) => entry.sessionId !== session.sessionId).concat(session);
  saveState();
}

function drawCard() {
  const availableCards = getAvailableCards();
  if (!availableCards.length) {
    state.currentCardSession = null;
    elements.cardCategory.textContent = "Keine Karte";
    elements.cardTitle.textContent = "Filter zu eng";
    elements.cardText.textContent = "Erhoeht die Intensitaet oder waehlt einen anderen Fokus.";
    clearCardCompletionPanel();
    updateCardActionState("idle");
    return;
  }

  const modeId = getSelectedCardMode();
  const context = buildCardDrawContext({ modeId, topic: getSelectedCardTopic(), drawerIndex: state.activeIndex });
  const commonCardCount = availableCards.filter((item) => !isScarceSwingerDominance(item)).length;
  const card = pickWithScarceThemeGate(
    getCardsForMode(availableCards, modeId, context),
    "cardHistory",
    (item) => `${item.category}:${item.title}`,
    (item) => cardWeight(item) + scoreCardForMode(item, modeId, context),
    antiRepeatLimit(commonCardCount || availableCards.length, 0.9)
  );
  const session = buildCardSession(card, context);
  finaliseCardSession(session, "preview");
  renderCardPreview(card, session);
}

function advanceRound() {
  state.round += 1;
  if (elements.takeTurns.checked) {
    state.activeIndex = state.activeIndex === 0 ? 1 : 0;
  }
  updateLabels();
  saveState();
}

function completeCard() {
  const session = state.currentCardSession;
  if (!session) {
    drawCard();
    return;
  }
  if (session.status === "preview") {
    acceptTask(session.card, buildCardDrawContext({ modeId: session.mode, topic: session.topic, drawerIndex: session.openedBy }));
    return;
  }
  if (session.status === "accepted" || session.status === "in_progress") {
    completeTask(session.taskId || state.activeTask?.id || "");
    return;
  }
  drawCard();
}

function skipCurrentCard() {
  const session = state.currentCardSession;
  if (!session) {
    drawCard();
    return;
  }
  if (session.status === "preview") {
    zapSuggestedTask(session.cardId || "", "zapped");
    return;
  }
  if (session.status === "accepted" || session.status === "in_progress") {
    abortTask(session.taskId || state.activeTask?.id || "");
    return;
  }
  drawCard();
}

function syncProfile() {
  const profileFieldsOne = readQuestionFields(elements.profileAnswersOne);
  const profileFieldsTwo = readQuestionFields(elements.profileAnswersTwo);
  const currentProfileOne = normalizeProfile(state.profiles[0]);
  const currentProfileTwo = normalizeProfile(state.profiles[1]);
  const previousPlayers = [...state.players];
  const previousLikesOne = state.likesOne;
  const previousLikesTwo = state.likesTwo;
  const rankingOne = readTryRanking(elements.profileTryRankingOne);
  const rankingTwo = readTryRanking(elements.profileTryRankingTwo);
  const answersOne = profileFieldsOne.answers;
  const answersTwo = profileFieldsTwo.answers;
  state.players = [
    elements.playerOne.value.trim() || "Christian",
    elements.playerTwo.value.trim() || "Jenny"
  ];
  const nextProfileOne = {
      about: elements.aboutOne.value,
      questions: elements.questionsOne.value,
      answers: answersOne,
      hiddenAnswers: profileFieldsOne.hiddenAnswers,
      tryRanking: rankingOne || currentProfileOne.tryRanking,
      setupComplete: state.profiles[0]?.setupComplete || Object.values(answersOne).some(Boolean)
  };
  const nextProfileTwo = {
      about: elements.aboutTwo.value,
      questions: elements.questionsTwo.value,
      answers: answersTwo,
      hiddenAnswers: profileFieldsTwo.hiddenAnswers,
      tryRanking: rankingTwo || currentProfileTwo.tryRanking,
      setupComplete: state.profiles[1]?.setupComplete || Object.values(answersTwo).some(Boolean)
  };
  state.profiles = [nextProfileOne, nextProfileTwo];
  state.boundaries = elements.boundaries?.value || state.boundaries;
  state.likesOne = elements.likesOne.value;
  state.likesTwo = elements.likesTwo.value;
  state.sharedGoals = elements.sharedGoals?.value || state.sharedGoals;
  queueProfileChangeMessage(0, summarizeProfileChanges(currentProfileOne, nextProfileOne, {
    beforeName: previousPlayers[0],
    afterName: state.players[0],
    beforeLikes: previousLikesOne,
    afterLikes: state.likesOne,
    profileIndex: 0
  }));
  queueProfileChangeMessage(1, summarizeProfileChanges(currentProfileTwo, nextProfileTwo, {
    beforeName: previousPlayers[1],
    afterName: state.players[1],
    beforeLikes: previousLikesTwo,
    afterLikes: state.likesTwo,
    profileIndex: 1
  }));
  updateLabels();
  saveState();
  elements.profileStatus.textContent = "Gespeichert.";
}

function markProfilesDirty() {
  if (elements.profileView && !elements.profileView.hidden && elements.selfProfileStatus) {
    elements.selfProfileStatus.textContent = "Aenderungen noch nicht gespeichert.";
    return;
  }
  if (elements.profileStatus) elements.profileStatus.textContent = "Aenderungen noch nicht gespeichert.";
}

function setActiveProfile(index) {
  state.activeIndex = index;
  updateLabels();
  if (!elements.profileView.hidden) renderSelfProfile();
  saveState();
}

function renderCustomCards() {
  elements.customList.innerHTML = "";
  state.customCards.forEach((card, index) => {
    const item = document.createElement("li");
    const text = document.createElement("span");
    const remove = document.createElement("button");

    text.textContent = `${card.title}: ${card.text}`;
    remove.type = "button";
    remove.textContent = "Loeschen";
    remove.addEventListener("click", () => {
      state.customCards.splice(index, 1);
      renderCustomCards();
      saveState();
    });

    item.append(text, remove);
    elements.customList.append(item);
  });
}

function addCustomCard() {
  const title = elements.customTitle.value.trim();
  const text = elements.customText.value.trim();
  if (!title || !text) return;

  state.customCards.push({
    title,
    text,
    category: elements.customCategory.value,
    intensity: Number(elements.intensityRange.value),
    tags: [elements.tagSelect.value].filter((tag) => tag !== "all")
  });

  elements.customTitle.value = "";
  elements.customText.value = "";
  renderCustomCards();
  saveState();
}

function openVaultDb() {
  if (dbPromise) return dbPromise;
  dbPromise = new Promise((resolve, reject) => {
    const request = indexedDB.open(dbName, 1);
    request.onupgradeneeded = () => {
      request.result.createObjectStore("media", { keyPath: "id" });
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
  return dbPromise;
}

function vaultTransaction(mode) {
  return openVaultDb().then((db) => db.transaction("media", mode).objectStore("media"));
}

function storeRequest(request) {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function cryptoReady() {
  return Boolean(window.crypto?.subtle && window.crypto?.getRandomValues && window.indexedDB);
}

function bytesToBase64(bytes) {
  let binary = "";
  bytes.forEach((byte) => {
    binary += String.fromCharCode(byte);
  });
  return btoa(binary);
}

function base64ToBytes(value) {
  return Uint8Array.from(atob(value), (char) => char.charCodeAt(0));
}

function bufferToBase64(buffer) {
  return bytesToBase64(new Uint8Array(buffer));
}

async function deriveVaultKey(password, salt) {
  const baseKey = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(password),
    "PBKDF2",
    false,
    ["deriveKey"]
  );
  return crypto.subtle.deriveKey(
    { name: "PBKDF2", salt, iterations: 250000, hash: "SHA-256" },
    baseKey,
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"]
  );
}

function getVaultSalt() {
  const saved = localStorage.getItem(vaultSaltKey);
  if (saved) {
    return Uint8Array.from(atob(saved), (char) => char.charCodeAt(0));
  }
  const salt = crypto.getRandomValues(new Uint8Array(16));
  localStorage.setItem(vaultSaltKey, bytesToBase64(salt));
  return salt;
}

async function createVaultVerifier(key) {
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const encrypted = await crypto.subtle.encrypt(
    { name: "AES-GCM", iv },
    key,
    new TextEncoder().encode(vaultVerifierPlain)
  );
  localStorage.setItem(vaultVerifierKey, JSON.stringify({
    iv: Array.from(iv),
    data: bufferToBase64(encrypted)
  }));
}

async function decryptRecordData(record, key = vaultKey) {
  if (!key) throw new Error("Vault locked");
  return crypto.subtle.decrypt(
    { name: "AES-GCM", iv: new Uint8Array(record.iv) },
    key,
    record.data
  );
}

async function verifyVaultPassword(key) {
  const saved = localStorage.getItem(vaultVerifierKey);
  if (saved) {
    try {
      const verifier = JSON.parse(saved);
      const plain = await crypto.subtle.decrypt(
        { name: "AES-GCM", iv: new Uint8Array(verifier.iv || []) },
        key,
        base64ToBytes(verifier.data || "")
      );
      return new TextDecoder().decode(plain) === vaultVerifierPlain;
    } catch (error) {
      return false;
    }
  }

  const records = await getAllMediaRecords().catch(() => []);
  if (records.length) {
    try {
      await decryptRecordData(records[0], key);
      await createVaultVerifier(key);
      return true;
    } catch (error) {
      return false;
    }
  }

  await createVaultVerifier(key);
  return true;
}

async function getVerifiedVaultKey(password) {
  if (!cryptoReady()) {
    throw new Error("Dieser Browser stellt keine starke Verschluesselung bereit.");
  }
  if (String(password || "").length < 10) {
    throw new Error("Bitte das gemeinsame Passwort mit mindestens 10 Zeichen eingeben.");
  }
  const key = await deriveVaultKey(password, getVaultSalt());
  const accepted = await verifyVaultPassword(key);
  if (!accepted) throw new Error("Passwort passt nicht. Medium wurde nicht gespeichert.");
  return key;
}

function clearVaultPreview() {
  vaultObjectUrls.forEach((url) => URL.revokeObjectURL(url));
  vaultObjectUrls = [];
  if (elements.mediaGrid) elements.mediaGrid.innerHTML = "";
}

function closeVault(message = "Private Bibliothek geschlossen.") {
  vaultKey = null;
  clearVaultPreview();
  if (elements.mediaInput) {
    elements.mediaInput.value = "";
    elements.mediaInput.disabled = true;
  }
  if (elements.lockVault) elements.lockVault.disabled = true;
  if (elements.vaultPassword) elements.vaultPassword.value = "";
  if (elements.vaultStatus) elements.vaultStatus.textContent = message;
}

function renderVaultState() {
  if (!vaultKey) {
    clearVaultPreview();
    if (elements.mediaInput) elements.mediaInput.disabled = true;
    if (elements.lockVault) elements.lockVault.disabled = true;
    if (elements.vaultStatus) elements.vaultStatus.textContent = "Private Bibliothek geschlossen.";
    return;
  }
  elements.mediaInput.disabled = false;
  elements.lockVault.disabled = false;
  renderMedia().catch(() => closeVault("Private Bibliothek wurde gesperrt. Passwort bitte neu eingeben."));
}

async function unlockVault() {
  if (!cryptoReady()) {
    elements.vaultStatus.textContent = "Dieser Browser stellt keine starke Verschluesselung bereit. Private Medien werden hier nicht gespeichert.";
    return;
  }

  const password = elements.vaultPassword.value;
  if (password.length < 10) {
    elements.vaultStatus.textContent = "Bitte ein Passwort mit mindestens 10 Zeichen verwenden.";
    return;
  }

  elements.unlockVault.disabled = true;
  elements.vaultStatus.textContent = "Pruefe Passwort...";

  try {
    const key = await getVerifiedVaultKey(password);

    vaultKey = key;
    elements.vaultPassword.value = "";
    elements.mediaInput.disabled = false;
    elements.lockVault.disabled = false;
    elements.vaultStatus.textContent = "Private Bibliothek offen. Neue Medien werden verschluesselt gespeichert.";
    await renderMedia();
  } catch (error) {
    closeVault("Private Bibliothek konnte nicht geoeffnet werden.");
  } finally {
    elements.unlockVault.disabled = false;
  }
}

async function encryptFile(file, metadata = {}, key = vaultKey) {
  if (!key) throw new Error("Private Bibliothek ist geschlossen.");
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const plain = await file.arrayBuffer();
  const encrypted = await crypto.subtle.encrypt({ name: "AES-GCM", iv }, key, plain);
  return {
    id: `${Date.now()}-${crypto.randomUUID ? crypto.randomUUID() : Math.random().toString(36).slice(2)}`,
    name: file.name,
    type: file.type,
    createdAt: new Date().toISOString(),
    ...metadata,
    iv: Array.from(iv),
    data: encrypted
  };
}

async function saveEncryptedMediaFile(file, metadata = {}, key = vaultKey) {
  const record = await encryptFile(file, metadata, key);
  const store = await vaultTransaction("readwrite");
  await storeRequest(store.put(record));
  return record;
}

async function addMediaFiles() {
  if (!vaultKey) {
    elements.vaultStatus.textContent = "Erst Passwort eingeben und Bibliothek oeffnen.";
    return;
  }
  const files = [...elements.mediaInput.files].filter((file) => /^(image|video|audio)\//.test(file.type));
  if (!files.length) {
    elements.mediaInput.value = "";
    elements.vaultStatus.textContent = "Nur Bilder, Videos und Audios werden gespeichert.";
    return;
  }
  for (const file of files) {
    await saveEncryptedMediaFile(file, {
      savedFrom: "library",
      sender: state.activeIndex,
      senderName: state.players[state.activeIndex],
      caption: ""
    });
  }
  elements.mediaInput.value = "";
  await renderMedia();
}

async function getAllMediaRecords() {
  const store = await vaultTransaction("readonly");
  return storeRequest(store.getAll());
}

async function deleteMedia(id) {
  if (!vaultKey) return;
  const store = await vaultTransaction("readwrite");
  await storeRequest(store.delete(id));
  await renderMedia();
}

async function decryptRecord(record) {
  const plain = await decryptRecordData(record);
  const url = URL.createObjectURL(new Blob([plain], { type: record.type }));
  vaultObjectUrls.push(url);
  return url;
}

async function renderMedia() {
  clearVaultPreview();
  if (!vaultKey) return;

  const records = (await getAllMediaRecords()).sort((a, b) => String(b.createdAt || "").localeCompare(String(a.createdAt || "")));
  if (!records.length) {
    elements.vaultStatus.textContent = "Private Bibliothek offen. Noch keine Medien gespeichert.";
    return;
  }

  elements.vaultStatus.textContent = `${records.length} verschluesselte Datei(en) im privaten Bereich.`;
  for (const record of records) {
    const item = document.createElement("article");
    const footer = document.createElement("footer");
    const name = document.createElement("span");
    const remove = document.createElement("button");
    let url = "";
    try {
      url = await decryptRecord(record);
    } catch (error) {
      closeVault("Passwort passt nicht oder eine Datei ist beschaedigt. Bibliothek wurde geschlossen.");
      return;
    }
    const media = record.type.startsWith("video/")
      ? document.createElement("video")
      : record.type.startsWith("audio/")
        ? document.createElement("audio")
        : document.createElement("img");

    item.className = "media-item";
    media.src = url;
    if (media.tagName === "VIDEO" || media.tagName === "AUDIO") media.controls = true;
    const sender = record.senderName ? `${record.senderName}: ` : "";
    const label = record.caption || record.name;
    name.textContent = `${sender}${label}`;
    name.title = [record.name, record.caption, record.sourceTitle].filter(Boolean).join(" - ");
    remove.type = "button";
    remove.textContent = "Loeschen";
    remove.addEventListener("click", () => deleteMedia(record.id));
    footer.append(name, remove);
    item.append(media, footer);
    elements.mediaGrid.append(item);
  }
}

