function setupPullToRefreshGuard() {
  let startY = 0;
  let tracking = false;
  let armed = false;
  document.addEventListener("touchstart", (event) => {
    const touch = event.touches?.[0];
    tracking = Boolean(touch) && window.scrollY <= 0 && !document.body.classList.contains("locked");
    armed = false;
    startY = touch?.clientY || 0;
    if (tracking) pullGestureGraceUntil = Date.now() + 1800;
  }, { passive: true });
  document.addEventListener("touchmove", (event) => {
    if (!tracking) return;
    const touch = event.touches?.[0];
    const distance = (touch?.clientY || 0) - startY;
    if (window.scrollY <= 0 && distance > 18) {
      armed = distance > 76;
      pullGestureGraceUntil = Date.now() + 1800;
      event.preventDefault();
    }
  }, { passive: false });
  document.addEventListener("touchend", () => {
    if (tracking && armed) {
      pullGestureGraceUntil = Date.now() + 2200;
      refreshCurrentViewFromPull();
    }
    tracking = false;
    armed = false;
  }, { passive: true });
}

